      const dateStr = currentDate.toISOString().split("T")[0];
  
      // Generate meal with nutrition targets
      const caloriesVariance = nutritionTargets.caloriesPerDay * 0.025;
      const proteinVariance = nutritionTargets.proteinGramsPerDay * 0.025;
      const fiberVariance = nutritionTargets.fiberGramsPerDay * 0.025;
      const saltVariance = nutritionTargets.saltGramsPerDay * 0.025;
  
