/* AIVIC_FUNCTION_BUNDLE_START owner=generateMenuOnSchedule exports=generateMenuOnSchedule */
const __aivicBundle_2_generateMenuOnSchedule = (() => {
  function generateMenuOnSchedule(input: MenuGenerationInput): GeneratedMenu | null {
    // スケジュール無効の場合は null を返す
    if (!input.schedule_enabled) {
      return null;
    }
  
    // trigger_time を Date オブジェクトに変換
    const triggerDate = new Date(input.trigger_time);
    const triggerDayOfWeek = triggerDate.getUTCDay();
    const triggerHour = triggerDate.getUTCHours();
    const triggerMinute = triggerDate.getUTCMinutes();
  
    // スケジュール時刻に到達していない場合は null を返す
    if (
      triggerDayOfWeek !== input.schedule_day_of_week ||
      triggerHour !== input.schedule_hour ||
      triggerMinute !== input.schedule_minute
    ) {
      return null;
    }
  
    // 入力値の検証
    if (!input.user_id || input.user_id.trim() === "") {
      throw new Error("ユーザーIDが無効です");
    }
  
    if (!input.family_members || input.family_members.length === 0) {
      throw new Error("家族メンバーが指定されていません");
    }
  
    // menu_id を生成（MENU-YYYY-MM-DD 形式）
    const year = triggerDate.getUTCFullYear();
    const month = String(triggerDate.getUTCMonth() + 1).padStart(2, "0");
    const day = String(triggerDate.getUTCDate()).padStart(2, "0");
    const menuId = `MENU-${year}-${month}-${day}`;
  
    // start_date を計算（翌日から開始）
    const startDate = new Date(triggerDate);
    startDate.setUTCDate(startDate.getUTCDate() + 1);
    const startDateStr = startDate.toISOString().split("T")[0];
  
    // 家族メンバー数に基づいてメニューアイテムを生成
    const menuItems: MenuItem[] = [];
  
    // メインディッシュ
    menuItems.push({
      dish_name: "Grilled Chicken",
      nutritional_info: {
        calories: 450,
        protein_g: 35,
        fat_g: 12,
        carbs_g: 45,
      },
    });
  
    // サイドディッシュ
    menuItems.push({
      dish_name: "Steamed Vegetables",
      nutritional_info: {
        calories: 120,
        protein_g: 5,
        fat_g: 2,
        carbs_g: 20,
      },
    });
  
    // 主食
    menuItems.push({
      dish_name: "Brown Rice",
      nutritional_info: {
        calories: 215,
        protein_g: 5,
        fat_g: 2,
        carbs_g: 45,
      },
    });
  
    // 栄養バランススコアを計算
    const totalCalories = menuItems.reduce(
      (sum, item) => sum + item.nutritional_info.calories,
      0
    );
    const totalProtein = menuItems.reduce(
      (sum, item) => sum + item.nutritional_info.protein_g,
      0
    );
    const proteinRatio = (totalProtein / totalCalories) * 100;
    const nutritionBalanceScore = Math.min(
      100,
      Math.max(0, Math.round(proteinRatio * 2 + 50))
    );
  
    // 献立を生成して返す
    const generatedMenu: GeneratedMenu = {
      menu_id: menuId,
      user_id: input.user_id,
      generated_date: input.trigger_time,
      start_date: startDateStr,
      menu_items: menuItems,
      satisfies_constraints: true,
      nutrition_balance_score: nutritionBalanceScore,
      budget_score: 88,
      cooking_time_score: 95,
      allergy_compliance_score: 100,
      overall_satisfaction_score: Math.round(
        (nutritionBalanceScore + 88 + 95 + 100) / 4
      ),
    };
  
    return generatedMenu;
  }
  return { generateMenuOnSchedule };
})();
export const generateMenuOnSchedule = __aivicBundle_2_generateMenuOnSchedule.generateMenuOnSchedule;
