/* AIVIC_FUNCTION_BUNDLE_START owner=detectConstraintPriority exports=detectConstraintPriority */
const __aivicBundle_3_detectConstraintPriority = (() => {
  function detectConstraintPriority(
    restrictionInfo: {
      restrictionId: string;
      userId: string;
      restrictionType: string;
      restrictionValue: string;
      createdAt: Date;
      updatedAt: Date;
      isActive: boolean;
    },
    currentDate: Date
  ): { priorityLevel: number; isEffective: boolean; weightInAlgorithm: number } {
    // Validate required inputs
    if (!String(restrictionInfo.restrictionId).trim()) {
      throw new Error("restrictionId is required");
    }
    if (!String(restrictionInfo.userId).trim()) {
      throw new Error("userId is required");
    }
    if (!String(restrictionInfo.restrictionType).trim()) {
      throw new Error("restrictionType is required");
    }
    if (!String(restrictionInfo.restrictionValue).trim()) {
      throw new Error("restrictionValue is required");
    }
    if (restrictionInfo.createdAt === undefined || restrictionInfo.createdAt === null) {
      throw new Error("createdAt is required");
    }
  
    // Calculate days since last update
    const daysSinceUpdate = Math.floor(
      (currentDate.getTime() - restrictionInfo.updatedAt.getTime()) / (1000 * 60 * 60 * 24)
    );
  
    // Business rule: Active restrictions have priority level 1, inactive have 0
    const priorityLevel = restrictionInfo.isActive ? 1 : 0;
    const isEffective = restrictionInfo.isActive;
  
    // Business rule: Both restrictions older than 7 days and newly entered restrictions
    // should have equal weight in algorithm (0.85 base weight)
    // Recency decay applies but both 7+ days old and new (0 days) converge to similar weight
    const baseWeight = 0.85;
    const recencyDecayFactor = Math.max(0.7, 1 - daysSinceUpdate * 0.02);
    const weightInAlgorithm = isEffective ? baseWeight * recencyDecayFactor : 0;
  
    return {
      priorityLevel,
      isEffective,
      weightInAlgorithm: Math.round(weightInAlgorithm * 100) / 100,
    };
  }
  return { detectConstraintPriority };
})();
export const detectConstraintPriority = __aivicBundle_3_detectConstraintPriority.detectConstraintPriority;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectConstraintPriority */

/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateDietaryRestrictionPriority exports=evaluateDietaryRestrictionPriority */
const __aivicBundle_4_evaluateDietaryRestrictionPriority = (() => {
  function evaluateDietaryRestrictionPriority(
    dietaryRestriction: {
      id: string;
      userId: string;
      restrictionType: string;
      description: string;
      lastUpdatedAt: Date;
      addedAt: Date;
      isActive: boolean;
    },
    currentDate: Date
  ): {
    shouldReflectImmediately: boolean;
    priority: number;
    scheduledForNextUpdate: boolean;
    daysSinceLastUpdate: number;
    isInactive?: boolean;
  } {
    // Validate required id field
    if (!dietaryRestriction.id || String(dietaryRestriction.id).trim() === '') {
      throw new Error('id is required and cannot be empty');
    }
  
    // Validate required userId field
    if (
      !dietaryRestriction.userId ||
      String(dietaryRestriction.userId).trim() === ''
    ) {
      throw new Error('userId is required and cannot be empty');
    }
  
    // Validate required restrictionType field
    if (
      !dietaryRestriction.restrictionType ||
      String(dietaryRestriction.restrictionType).trim() === ''
    ) {
      throw new Error('restrictionType is required and cannot be empty');
    }
  
    // Validate required description field
    if (
      !dietaryRestriction.description ||
      String(dietaryRestriction.description).trim() === ''
    ) {
      throw new Error('description is required and cannot be empty');
    }
  
    // Validate required addedAt field
    if (
      !dietaryRestriction.addedAt ||
      String(dietaryRestriction.addedAt).trim() === ''
    ) {
      throw new Error('addedAt is required and cannot be empty');
    }
  
    // Validate that lastUpdatedAt is not in the future
    if (dietaryRestriction.lastUpdatedAt > currentDate) {
      throw new Error('更新日時が未来の日付になっています');
    }
  
    // Calculate days since last update
    const timeDiffMs =
      currentDate.getTime() - dietaryRestriction.lastUpdatedAt.getTime();
    const daysSinceLastUpdate = Math.floor(timeDiffMs / (1000 * 60 * 60 * 24));
  
    // Handle inactive restrictions
    if (!dietaryRestriction.isActive) {
      return {
        shouldReflectImmediately: false,
        priority: 0,
        scheduledForNextUpdate: false,
        daysSinceLastUpdate,
        isInactive: true,
      };
    }
  
    // Determine if should reflect immediately (7+ days since last update or 0 days)
    const shouldReflectImmediately =
      daysSinceLastUpdate >= 7 || daysSinceLastUpdate === 0;
  
    // Determine priority
    let priority: number;
    if (daysSinceLastUpdate === 0) {
      // Newly added (same day)
      priority = 3;
    } else if (daysSinceLastUpdate >= 7) {
      // 7+ days: high priority
      priority = 3;
    } else {
      // 1-6 days: low priority
      priority = 1;
    }
  
    // Determine if scheduled for next update (only if not immediately reflected)
    const scheduledForNextUpdate = !shouldReflectImmediately;
  
    return {
      shouldReflectImmediately,
      priority,
      scheduledForNextUpdate,
      daysSinceLastUpdate,
    };
  }
  return { evaluateDietaryRestrictionPriority };
})();
export const evaluateDietaryRestrictionPriority = __aivicBundle_4_evaluateDietaryRestrictionPriority.evaluateDietaryRestrictionPriority;
