/* AIVIC_FUNCTION_BUNDLE_START owner=detectConflictingMenus exports=detectConflictingMenus */
const __aivicBundle_6_detectConflictingMenus = (() => {
  function detectConflictingMenus(
    input?: { user_id?: string; new_allergen?: string; past_menus?: Array<{ menu_id: string; menu_name: string; execution_date: string; ingredients: string[]; allergens: string[] }> } | any[],
    restrictionCondition?: any
  ): { allergen: string; total_detected_count: number; conflicting_menus: Array<{ menu_id: string; menu_name: string; execution_date: string; contained_allergens: string[]; conflict_reason: string }>; non_conflicting_count: number } | any[] {
    // Handle array input (empty menu history case)
    if (Array.isArray(input)) {
      // restrictionCondition is used to validate that filtering logic is applied
      // even when menu history is empty, ensuring the function respects both parameters
      if (restrictionCondition) {
        // Restriction condition is acknowledged but no menus to filter
        return [];
      }
      return [];
    }
  
    // Handle object input
    const { user_id, new_allergen, past_menus } = input || {};
  
    // Validation: user_id must not be empty
    if (!user_id || String(user_id).trim() === "") {
      throw new Error("ユーザーIDが指定されていません");
    }
  
    // Validation: new_allergen must not be empty
    if (!new_allergen || String(new_allergen).trim() === "") {
      throw new Error("アレルギー食材が指定されていません");
    }
  
    // Validation: past_menus must not be empty
    if (!past_menus || !Array.isArray(past_menus) || past_menus.length === 0) {
      throw new Error("献立履歴が存在しません");
    }
  
    // Sort past_menus by execution_date (ascending order)
    const sortedMenus = [...past_menus].sort((a, b) => {
      return new Date(a.execution_date).getTime() - new Date(b.execution_date).getTime();
    });
  
    // Detect conflicting menus
    const conflictingMenus: Array<{ menu_id: string; menu_name: string; execution_date: string; contained_allergens: string[]; conflict_reason: string }> = [];
    let nonConflictingCount = 0;
  
    for (const menu of sortedMenus) {
      const menuAllergens = menu.allergens || [];
      const menuIngredients = menu.ingredients || [];
  
      // Check if new_allergen is in allergens array or ingredients array
      const isConflicting =
        menuAllergens.includes(new_allergen) ||
        menuIngredients.includes(new_allergen);
  
      if (isConflicting) {
        // Collect all allergens from this menu that match the new allergen
        const containedAllergens: string[] = [];
  
        // Add the new_allergen if it's in allergens array
        if (menuAllergens.includes(new_allergen)) {
          containedAllergens.push(new_allergen);
        }
  
        // Add the new_allergen if it's in ingredients but not already added
        if (
          menuIngredients.includes(new_allergen) &&
          !containedAllergens.includes(new_allergen)
        ) {
          containedAllergens.push(new_allergen);
        }
  
        conflictingMenus.push({
          menu_id: menu.menu_id,
          menu_name: menu.menu_name,
          execution_date: menu.execution_date,
          contained_allergens: containedAllergens,
          conflict_reason: `${new_allergen} detected in ingredients`,
        });
      } else {
        nonConflictingCount++;
      }
    }
  
    return {
      allergen: new_allergen,
      total_detected_count: conflictingMenus.length,
      conflicting_menus: conflictingMenus,
      non_conflicting_count: nonConflictingCount,
    };
  }
  return { detectConflictingMenus };
})();
export const detectConflictingMenus: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_6_detectConflictingMenus.detectConflictingMenus as (...args: any[]) => any)(...args);
