/* AIVIC_FUNCTION_BUNDLE_START owner=detectInvalidAllergyInfo exports=detectInvalidAllergyInfo */
const __aivicBundle_8_detectInvalidAllergyInfo = (() => {
  function detectInvalidAllergyInfo(input: {
    allergen_name: string | null | undefined;
    severity_level: string;
    user_id: string;
  }): { is_valid: boolean; error_message: string | null; error_log_entry: string | null } {
    // Validate allergen_name
    if (input.allergen_name === null || input.allergen_name === undefined) {
      throw new Error('アレルギー名が無効です');
    }
  
    const allergenName = String(input.allergen_name).trim();
  
    // Check for empty or whitespace-only
    if (allergenName.length === 0) {
      throw new Error('アレルギー名が無効です');
    }
  
    // Check for numeric-only input
    if (/^\d+$/.test(allergenName)) {
      throw new Error('アレルギー名が無効です');
    }
  
    // Check for XSS injection patterns (HTML/script tags)
    if (/<[^>]*>/g.test(allergenName)) {
      throw new Error('アレルギー名が無効です');
    }
  
    // Check for SQL injection patterns
    if (/['";\\-]/g.test(allergenName)) {
      throw new Error('アレルギー名が無効です');
    }
  
    // Check for disallowed special characters (allow only alphanumeric, spaces, hyphens, parentheses)
    if (!/^[a-zA-Z0-9\s\-()]+$/.test(allergenName)) {
      throw new Error('アレルギー名が無効です');
    }
  
    // Check length constraint (max 255 characters)
    if (allergenName.length > 255) {
      throw new Error('アレルギー名が無効です');
    }
  
    // Validate severity_level
    const validSeverityLevels = ['low', 'medium', 'high', 'critical'];
    if (!validSeverityLevels.includes(input.severity_level)) {
      throw new Error('重症度レベルが無効です');
    }
  
    // Validate user_id
    if (!input.user_id || input.user_id.trim().length === 0) {
      throw new Error('ユーザーIDが無効です');
    }
  
    // All validations passed
    return {
      is_valid: true,
      error_message: null,
      error_log_entry: null
    };
  }
  return { detectInvalidAllergyInfo };
})();
export const detectInvalidAllergyInfo = __aivicBundle_8_detectInvalidAllergyInfo.detectInvalidAllergyInfo;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectInvalidAllergyInfo */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMenuConstraintFulfillmentScores exports=calculateMenuConstraintFulfillmentScores */
const __aivicBundle_9_calculateMenuConstraintFulfillmentScores = (() => {
  function calculateMenuConstraintFulfillmentScores(
    input: {
      menu_id: string;
      nutrition_target: {
        protein_g: number;
        carbs_g: number;
        fat_g: number;
      };
      nutrition_actual: {
        protein_g: number;
        carbs_g: number;
        fat_g: number;
      };
      allergen_exclusions: string[];
      allergen_actual: string[];
      budget_limit_yen: number;
      budget_actual_yen: number;
      cooking_time_limit_min: number;
      cooking_time_actual_min: number;
    }
  ): ConstraintFulfillmentScores {
    if (!String(input.menu_id).trim()) {
      throw new Error("menu_id is required");
    }
  
    const {
      nutrition_target,
      nutrition_actual,
      allergen_exclusions,
      allergen_actual,
      budget_limit_yen,
      budget_actual_yen,
      cooking_time_limit_min,
      cooking_time_actual_min,
    } = input;
  
    if (
      !nutrition_target ||
      nutrition_target.protein_g === undefined ||
      nutrition_target.carbs_g === undefined ||
      nutrition_target.fat_g === undefined
    ) {
      throw new Error("栄養目標に必須フィールドが不足しています");
    }
  
    if (budget_limit_yen < 0) {
      throw new Error("予算制限は0以上である必要があります");
    }
  
    if (cooking_time_limit_min <= 0) {
      throw new Error("調理時間制限は0より大きい値である必要があります");
    }
  
    const proteinRatio = nutrition_actual.protein_g / nutrition_target.protein_g;
    const carbsRatio = nutrition_actual.carbs_g / nutrition_target.carbs_g;
    const fatRatio = nutrition_actual.fat_g / nutrition_target.fat_g;
  
    const proteinScore = Math.min(proteinRatio * 100, 100);
    const carbsScore = Math.min(carbsRatio * 100, 100);
    const fatScore = Math.min(fatRatio * 100, 100);
  
    const nutrition_fulfillment_score = Math.round(
      (proteinScore + carbsScore + fatScore) / 3
    );
  
    const hasAllergenViolation = allergen_actual.some((allergen) =>
      allergen_exclusions.includes(allergen)
    );
  
    const allergen_fulfillment_score = hasAllergenViolation ? 0 : 100;
  
    const budget_fulfillment_score =
      budget_actual_yen > budget_limit_yen
        ? 0
        : Math.round(
            ((budget_limit_yen - budget_actual_yen) / budget_limit_yen) * 100
          );
  
    const cooking_time_fulfillment_score =
      cooking_time_actual_min > cooking_time_limit_min
        ? 0
        : Math.round(
            ((cooking_time_limit_min - cooking_time_actual_min) /
              cooking_time_limit_min) *
              100
          );
  
    const overallEvaluationScore =
      nutrition_fulfillment_score * 0.25 +
      allergen_fulfillment_score * 0.25 +
      budget_fulfillment_score * 0.25 +
      cooking_time_fulfillment_score * 0.25;
  
    const constraintViolations: any[] = [];
  
    if (hasAllergenViolation) {
      constraintViolations.push({
        type: "allergen",
        violatingAllergens: allergen_actual.filter((a) =>
          allergen_exclusions.includes(a)
        ),
      });
    }
  
    if (budget_actual_yen > budget_limit_yen) {
      constraintViolations.push({
        type: "budget",
        excess: budget_actual_yen - budget_limit_yen,
      });
    }
  
    if (cooking_time_actual_min > cooking_time_limit_min) {
      constraintViolations.push({
        type: "cooking_time",
        excess: cooking_time_actual_min - cooking_time_limit_min,
      });
    }
  
    const recommendedAdjustments: string[] = [];
  
    if (nutrition_fulfillment_score < 100) {
      recommendedAdjustments.push("栄養バランスを改善してください");
    }
  
    if (budget_fulfillment_score < 100) {
      recommendedAdjustments.push("予算内に収まるよう食材を調整してください");
    }
  
    if (cooking_time_fulfillment_score < 100) {
      recommendedAdjustments.push("調理時間を短縮できるメニューを検討してください");
    }
  
    return {
      nutrition_fulfillment_score,
      allergen_fulfillment_score,
      budget_fulfillment_score,
      cooking_time_fulfillment_score,
      overallEvaluationScore,
      constraintViolations,
      recommendedAdjustments,
    };
  }
  return { calculateMenuConstraintFulfillmentScores };
})();
