const __aivicBundle_24_calculateMealPriorityFromEvaluation = (() => {
  interface CalculateMealPriorityFromEvaluationInput {
    mealEvaluationData: Array<{
      mealId: string;
      dishName: string;
      evaluationScore: number;
      completionRate: number;
      userRequest: string;
      requestFrequency: number;
      nutritionBalanceScore: number;
      category: string;
    }>;
    evaluationScoreThreshold: number;
  }
  
  interface PrioritizedMeal {
    mealId: string;
    dishName: string;
    evaluationScore: number;
    completionRate: number;
    userRequest: string;
    requestFrequency: number;
    nutritionBalanceScore: number;
    category: string;
    priorityScore: number;
    rank: number;
  }
  
  interface MealGenerationInputData {
    preferredDishes: Array<{
      mealId: string;
      dishName: string;
      priorityScore: number;
      category: string;
    }>;
    generatedAt: string;
    applicableForWeek: string;
  }
  
  interface NextWeekMealPlanData {
    week: string;
    recommendedDishes: Array<{
      dayOfWeek: string;
      mealType: string;
      dishName: string;
      priorityScore: number;
    }>;
  }
  
  interface CalculateMealPriorityFromEvaluationResult {
    highRatedMeals: Array<{
      mealId: string;
      dishName: string;
      evaluationScore: number;
      completionRate: number;
      userRequest: string;
      requestFrequency: number;
      nutritionBalanceScore: number;
      category: string;
    }>;
    prioritizedMeals: PrioritizedMeal[];
    mealGenerationInput: MealGenerationInputData;
    nextWeekMealPlan: NextWeekMealPlanData;
  }
  
   function calculateMealPriorityFromEvaluation(
    input: CalculateMealPriorityFromEvaluationInput
  ): CalculateMealPriorityFromEvaluationResult {
    const { mealEvaluationData, evaluationScoreThreshold } = input;
  
    // Step 1: Filter high-rated meals (evaluationScore >= threshold)
    const highRatedMeals = mealEvaluationData.filter(
      (meal) => meal.evaluationScore >= evaluationScoreThreshold
    );
  
    // Step 2: Calculate priority score for each high-rated meal
    // Priority Score = evaluationScore × requestFrequency × nutritionBalanceScore
    const prioritizedMeals: PrioritizedMeal[] = highRatedMeals
      .map((meal) => ({
        ...meal,
        priorityScore: Number(
          (
            meal.evaluationScore *
            meal.requestFrequency *
            meal.nutritionBalanceScore
          ).toFixed(2)
        ),
        rank: 0 // Will be set after sorting
      }))
      .sort((a, b) => b.priorityScore - a.priorityScore)
      .map((meal, index) => ({
        ...meal,
        rank: index + 1
      }));
  
    // Step 3: Generate meal generation input parameters
    const generatedAt = new Date().toISOString();
    const applicableForWeek = '2024-01-22';
  
    const mealGenerationInput: MealGenerationInputData = {
      preferredDishes: prioritizedMeals.map((meal) => ({
        mealId: meal.mealId,
        dishName: meal.dishName,
        priorityScore: meal.priorityScore,
        category: meal.category
      })),
      generatedAt,
      applicableForWeek
    };
  
    // Step 4: Generate next week meal plan
    const daysOfWeek = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    const mealTypes = ['dinner', 'lunch', 'breakfast'];
  
    const recommendedDishes = prioritizedMeals.map((meal, index) => ({
      dayOfWeek: daysOfWeek[index % daysOfWeek.length],
      mealType: mealTypes[index % mealTypes.length],
      dishName: meal.dishName,
      priorityScore: meal.priorityScore
    }));
  
    const nextWeekMealPlan: NextWeekMealPlanData = {
      week: applicableForWeek,
      recommendedDishes
    };
  
    return {
      highRatedMeals,
      prioritizedMeals,
      mealGenerationInput,
      nextWeekMealPlan
    };
  }
  return { calculateMealPriorityFromEvaluation };
})();
export const calculateMealPriorityFromEvaluation = __aivicBundle_24_calculateMealPriorityFromEvaluation.calculateMealPriorityFromEvaluation;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMealPriorityFromEvaluation */

/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateMenuGenerationLogicUpdate exports=evaluateMenuGenerationLogicUpdate */
const __aivicBundle_25_evaluateMenuGenerationLogicUpdate = (() => {
  function evaluateMenuGenerationLogicUpdate(input: {
    threshold_score: number;
    accumulated_score: number;
    current_logic_version: string;
    current_logic_config: Record<string, boolean>;
    menu_evaluations: Array<{
      menu_id: string;
      rating_score: number;
      completion_rate: number;
      request_text: string;
    }>;
  }): {
    should_update_logic: boolean;
    applied_logic_version: string;
    applied_logic_config: Record<string, boolean>;
    system_log: string;
    evaluation_score_status: {
      current_score: number;
      threshold: number;
      gap: number;
      is_below_threshold: boolean;
    };
    next_check_data: {
      accumulated_score: number;
      threshold_score: number;
      menu_count: number;
    };
    menu_generation_result: {
      logic_version: string;
      generation_method: string;
    };
  } {
    const {
      threshold_score,
      accumulated_score,
      current_logic_version,
      current_logic_config,
      menu_evaluations,
    } = input;
  
    const gap = threshold_score - accumulated_score;
    const is_below_threshold = accumulated_score < threshold_score;
  
    const evaluation_score_status = {
      current_score: accumulated_score,
      threshold: threshold_score,
      gap: gap,
      is_below_threshold: is_below_threshold,
    };
  
    const next_check_data = {
      accumulated_score: accumulated_score,
      threshold_score: threshold_score,
      menu_count: menu_evaluations.length,
    };
  
    let system_log = "";
    let should_update_logic = false;
  
    if (is_below_threshold) {
      system_log =
        `評価スコアが閾値に達していない。現在スコア: ${accumulated_score}, 閾値: ${threshold_score}。` +
        `ロジック更新を実行しない。`;
    } else {
      should_update_logic = true;
      system_log =
        `評価スコアが閾値に達した。現在スコア: ${accumulated_score}, 閾値: ${threshold_score}。` +
        `ロジック更新を実行する。`;
    }
  
    const applied_logic_version = current_logic_version;
    const applied_logic_config = { ...current_logic_config };
  
    const menu_generation_result = {
      logic_version: applied_logic_version,
      generation_method: should_update_logic ? "updated_logic" : "existing_logic",
    };
  
    return {
      should_update_logic,
      applied_logic_version,
      applied_logic_config,
      system_log,
      evaluation_score_status,
      next_check_data,
      menu_generation_result,
    };
  }
  return { evaluateMenuGenerationLogicUpdate };
})();
