/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionAchievementRate exports=calculateNutritionAchievementRate */
const __aivicBundle_29_calculateNutritionAchievementRate = (() => {
  interface CalculateNutritionAchievementRateResult {
    proteinAchievementRate: number;
    fatAchievementRate: number;
    carbohydrateAchievementRate: number;
    carbohydratesAchievementRate?: number;
    overallAchievementRate: number;
  }
  
   function calculateNutritionAchievementRate(
    targetOrUserId: string | { protein?: number; carbohydrate?: number; carbohydrates?: number; fat?: number },
    actualsOrTargets?: { protein?: number; carbohydrate?: number; carbohydrates?: number; fat?: number },
    mealRecords?: any[]
  ): CalculateNutritionAchievementRateResult {
    // Case 1: 3 arguments with userId, targets, mealRecords
    if (typeof targetOrUserId === "string" && actualsOrTargets && Array.isArray(mealRecords)) {
      const userId = targetOrUserId;
      if (mealRecords.length === 0) {
        const error = new Error(`食事記録が見つかりません (userId: ${userId})`);
        (error as any).statusCode = 400;
        throw error;
      }
      // Would aggregate meal records here, but for now return placeholder
      return {
        proteinAchievementRate: 0,
        fatAchievementRate: 0,
        carbohydrateAchievementRate: 0,
        overallAchievementRate: 0,
      };
    }
  
    // Case 2: 2 arguments with targets and actuals objects
    const targets = targetOrUserId as { protein?: number; carbohydrate?: number; carbohydrates?: number; fat?: number };
    const actuals = actualsOrTargets as { protein?: number; carbohydrate?: number; carbohydrates?: number; fat?: number };
  
    const targetProtein = targets.protein ?? 0;
    const targetFat = targets.fat ?? 0;
    const targetCarbs = targets.carbohydrate ?? targets.carbohydrates ?? 0;
  
    const actualProtein = actuals.protein ?? 0;
    const actualFat = actuals.fat ?? 0;
    const actualCarbs = actuals.carbohydrate ?? actuals.carbohydrates ?? 0;
  
    const proteinAchievementRate =
      targetProtein > 0 ? Math.min((actualProtein / targetProtein) * 100, 100) : 0;
    const fatAchievementRate =
      targetFat > 0 ? Math.min((actualFat / targetFat) * 100, 100) : 0;
    const carbohydrateAchievementRate =
      targetCarbs > 0 ? Math.min((actualCarbs / targetCarbs) * 100, 100) : 0;
  
    const overallAchievementRate =
      (proteinAchievementRate + fatAchievementRate + carbohydrateAchievementRate) / 3;
  
    return {
      proteinAchievementRate,
      fatAchievementRate,
      carbohydrateAchievementRate,
      carbohydratesAchievementRate: carbohydrateAchievementRate,
      overallAchievementRate,
    };
  }
  return { calculateNutritionAchievementRate };
})();
