/* AIVIC_FUNCTION_BUNDLE_START owner=generateNotificationForImprovement exports=generateNotificationForImprovement */
const __aivicBundle_31_generateNotificationForImprovement = (() => {
  function generateNotificationForImprovement(
    improvementProposal: any
  ): {
    notificationSent: boolean;
    notificationContent: string;
    recommendedSprintSlot: 'current' | 'next' | 'backlog';
    impactScore: number;
  } {
    // Validate priority is defined
    if (improvementProposal.priority === undefined) {
      throw new Error('優先度が未設定です');
    }
  
    // Extract fields with fallback for different property names
    
    const proposalContent = improvementProposal.proposalContent || improvementProposal.content;
    const priorityLevel = improvementProposal.priorityLevel || improvementProposal.priority;
    const affectedUserCount = improvementProposal.affectedUserCount || 0;
    const estimatedImplementationDays = improvementProposal.estimatedImplementationDays || 0;
  
    // Calculate impact score based on priority, affected users, and implementation days
    let priorityScore = 0;
    if (priorityLevel === 'high') {
      priorityScore = 60;
    } else if (priorityLevel === 'medium') {
      priorityScore = 40;
    } else if (priorityLevel === 'low') {
      priorityScore = 20;
    }
  
    // User impact factor (normalized to 0-25)
    const userImpactFactor = Math.min(25, (affectedUserCount / 100) * 25);
  
    // Implementation effort factor (inverse: fewer days = higher score, 0-15)
    const effortFactor = Math.max(0, 15 - (estimatedImplementationDays / 2));
  
    const impactScore = Math.round(priorityScore + userImpactFactor + effortFactor);
  
    // Determine recommended sprint slot based on impact score and priority
    let recommendedSprintSlot: 'current' | 'next' | 'backlog';
    if (priorityLevel === 'high' && impactScore >= 70) {
      recommendedSprintSlot = 'current';
    } else if (priorityLevel === 'medium' || (priorityLevel === 'high' && impactScore < 70)) {
      recommendedSprintSlot = 'next';
    } else {
      recommendedSprintSlot = 'backlog';
    }
  
    // Generate notification content
    const notificationContent = `Proposal: ${proposalContent} | Priority: ${priorityLevel} | Affected Users: ${affectedUserCount} | Recommended Sprint: ${recommendedSprintSlot}`;
  
    return {
      notificationSent: false,
      notificationContent,
      recommendedSprintSlot,
      impactScore,
    };
  }
  return { generateNotificationForImprovement };
})();
