/* AIVIC_FUNCTION_BUNDLE_START owner=categorizeMenuRejectionReasons exports=categorizeMenuRejectionReasons */
const __aivicBundle_36_categorizeMenuRejectionReasons = (() => {
  function categorizeMenuRejectionReasons(
    rejectionReasons: Array<{ id?: number; userId?: string; reason?: string; text?: string; timestamp?: Date; createdAt?: string }>
  ): Array<{ id?: number; category: string; confidence?: number }> {
    if (!rejectionReasons || rejectionReasons.length === 0) {
      return [];
    }
  
    const categoryKeywords: Record<string, string[]> = {
      budgetExcess: ['予算', '高い', '割高', 'コスト', '超過'],
      nutritionBalance: ['栄養', 'タンパク質', 'ビタミン', 'カルシウム', '塩分', '食物繊維', '鉄分', '脂質'],
      ingredientUnavailable: ['入手困難', '品切れ', '季節外れ'],
      familyPreference: ['嗜好', '食べない', '辛すぎる', '海鮮'],
      cookingTimeTooLong: ['調理時間', '忙しい', '家事時間'],
    };
  
    const categorized = rejectionReasons.map((item) => {
      const reasonText = (item.reason || item.text || '').toLowerCase();
      let bestCategory = '不明';
      let bestScore = 0;
  
      for (const [category, keywords] of Object.entries(categoryKeywords)) {
        const matchCount = keywords.filter((kw) => reasonText.includes(kw)).length;
        if (matchCount > bestScore) {
          bestScore = matchCount;
          bestCategory = category;
        }
      }
  
      return {
        id: item.id,
        category: bestCategory,
        confidence: bestScore > 0 ? Math.min(0.95, 0.5 + bestScore * 0.15) : 0.2,
      };
    });
  
    return categorized;
  }
  return { categorizeMenuRejectionReasons };
})();
