/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateFailurePatterns exports=aggregateFailurePatterns */
const __aivicBundle_37_aggregateFailurePatterns = (() => {
  interface AggregateFailurePatternsResult {
    totalRejections: number;
    categoryBreakdown: {
      nutritionBalance?: { count: number; percentage: number };
      budgetExcess?: { count: number; percentage: number };
      ingredientUnavailable?: { count: number; percentage: number };
      preferenceDisagreement?: { count: number; percentage: number };
      cookingTimeTooLong?: { count: number; percentage: number };
      [key: string]: { count: number; percentage: number } | undefined;
    };
    temporalTrend: {
      weekly: Array<{
        weekStartDate: string;
        weekEndDate: string;
        rejectionCount: number;
        categoryDistribution: Record<string, number>;
      }>;
    };
  }
  
  interface CategorizedRejection {
    id: number;
    userId: string;
    reason: string;
    createdAt: string;
    category?: string;
  }
  
  interface AggregationPeriod {
    startDate: string;
    endDate: string;
  }
  
   function aggregateFailurePatterns(
    classificationResults: unknown,
    timeWindow: unknown
  ): AggregateFailurePatternsResult {
    const results = classificationResults as CategorizedRejection[];
    const period = timeWindow as AggregationPeriod;
  
    const startDate = new Date(period.startDate);
    const endDate = new Date(period.endDate);
  
    const filteredResults = results.filter((item) => {
      const itemDate = new Date(item.createdAt);
      return itemDate >= startDate && itemDate <= endDate;
    });
  
    const categoryCount: Record<string, number> = {};
    const weeklyData: Map<string, Map<string, number>> = new Map();
  
    for (const item of filteredResults) {
      const category = item.category || 'unknown';
      categoryCount[category] = (categoryCount[category] || 0) + 1;
  
      const itemDate = new Date(item.createdAt);
      const weekStart = new Date(itemDate);
      weekStart.setDate(itemDate.getDate() - itemDate.getDay());
      weekStart.setHours(0, 0, 0, 0);
  
      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekStart.getDate() + 6);
      weekEnd.setHours(23, 59, 59, 999);
  
      const weekKey = weekStart.toISOString().split('T')[0];
  
      if (!weeklyData.has(weekKey)) {
        weeklyData.set(weekKey, new Map());
      }
      const weekCategories = weeklyData.get(weekKey)!;
      weekCategories.set(category, (weekCategories.get(category) || 0) + 1);
    }
  
    const totalRejections = filteredResults.length;
  
    const categoryBreakdown: Record<string, { count: number; percentage: number }> = {};
    for (const [category, count] of Object.entries(categoryCount)) {
      const percentage =
        totalRejections > 0
          ? Math.round((count / totalRejections) * 10000) / 100
          : 0;
      categoryBreakdown[category] = { count, percentage };
    }
  
    const weeklyTrend: Array<{
      weekStartDate: string;
      weekEndDate: string;
      rejectionCount: number;
      categoryDistribution: Record<string, number>;
    }> = [];
  
    const sortedWeeks = Array.from(weeklyData.keys()).sort();
    for (const weekKey of sortedWeeks) {
      const weekStart = new Date(weekKey);
      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekStart.getDate() + 6);
  
      const categoryCounts = weeklyData.get(weekKey)!;
      const weekTotal = Array.from(categoryCounts.values()).reduce(
        (sum, count) => sum + count,
        0
      );
  
      const categoryDistribution: Record<string, number> = {};
      for (const [cat, count] of categoryCounts.entries()) {
        categoryDistribution[cat] = count;
      }
  
      weeklyTrend.push({
        weekStartDate: weekStart.toISOString().split('T')[0],
        weekEndDate: weekEnd.toISOString().split('T')[0],
        rejectionCount: weekTotal,
        categoryDistribution,
      });
    }
  
    return {
      totalRejections,
      categoryBreakdown,
      temporalTrend: {
        weekly: weeklyTrend,
      },
    };
  }
  return { aggregateFailurePatterns };
})();
export const aggregateFailurePatterns = __aivicBundle_37_aggregateFailurePatterns.aggregateFailurePatterns;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateFailurePatterns */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculatePriorityScores exports=calculatePriorityScores */
const __aivicBundle_38_calculatePriorityScores = (() => {
  function calculatePriorityScores(
    failurePatterns: any
  ): Array<{ pattern?: string; category?: string; priorityScore?: number; score?: number; priority: 'high' | 'medium' | 'low'; frequency?: number; importance?: number }> {
    // Handle both FailurePattern[] and aggregated object with categoryBreakdown
    let patterns: Array<{
      pattern?: string;
      category?: string;
      frequency: number;
      impactScore?: number;
      importance?: number;
      count?: number;
    }> = [];
  
    if (Array.isArray(failurePatterns)) {
      // Direct array of FailurePattern
      patterns = failurePatterns.map((fp) => ({
        pattern: fp.pattern,
        frequency: fp.frequency,
        impactScore: fp.impactScore,
      }));
    } else if (failurePatterns && typeof failurePatterns === 'object' && failurePatterns.categoryBreakdown) {
      // Aggregated object with categoryBreakdown
      const breakdown = failurePatterns.categoryBreakdown;
      
  
      patterns = Object.entries(breakdown).map(([category, data]: [string, any]) => ({
        category,
        frequency: data.count || 0,
        impactScore: data.impactScore || 0,
        importance: data.importance || 0,
        count: data.count || 0,
      }));
    }
  
    if (patterns.length === 0) {
      return [];
    }
  
    // Calculate priority scores
    const maxFrequency = Math.max(...patterns.map((p) => p.frequency || 0), 1);
    const maxImpact = Math.max(...patterns.map((p) => p.impactScore || 0), 1);
  
    const results = patterns.map((pattern) => {
      const frequencyNorm = (pattern.frequency || 0) / maxFrequency;
      const impactNorm = (pattern.impactScore || 0) / maxImpact;
      const importanceWeight = pattern.importance || 0.5;
  
      // Weighted score calculation: 40% frequency + 40% impact + 20% importance
      const priorityScore = Math.round(
        (frequencyNorm * 0.4 + impactNorm * 0.4 + importanceWeight * 0.2) * 100 * 100
      ) / 100;
  
      // Determine priority level based on score
      let priority: 'high' | 'medium' | 'low';
      if (priorityScore >= 20) {
        priority = 'high';
      } else if (priorityScore >= 10) {
        priority = 'medium';
      } else {
        priority = 'low';
      }
  
      const result: any = {
        priority,
        score: priorityScore,
        priorityScore,
      };
  
      if (pattern.pattern) {
        result.pattern = pattern.pattern;
      }
      if (pattern.category) {
        result.category = pattern.category;
      }
      if (pattern.frequency !== undefined) {
        result.frequency = Math.round(((pattern.frequency || 0) / (failurePatterns.totalRejections || 1)) * 100 * 100) / 100;
      }
      if (pattern.importance !== undefined) {
        result.importance = pattern.importance;
      }
  
      return result;
    });
  
    // Sort by score descending
    results.sort((a, b) => (b.score || 0) - (a.score || 0));
  
    return results;
  }
  return { calculatePriorityScores };
})();
export const calculatePriorityScores = __aivicBundle_38_calculatePriorityScores.calculatePriorityScores;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculatePriorityScores */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateDivergenceScore exports=calculateDivergenceScore */
const __aivicBundle_39_calculateDivergenceScore = (() => {
  interface CalculateDivergenceScoreInput {
    forecast_value: number;
    actual_value: number;
    category?: string;
    period_type?: string;
    period_id?: string;
    unit?: string;
  }
  
   function calculateDivergenceScore(
    input: CalculateDivergenceScoreInput
  ): number {
    const { forecast_value, actual_value } = input;
  
    if (actual_value === 0) {
      return 0;
    }
  
    const divergence = Math.abs(forecast_value - actual_value) / actual_value * 100;
  
    return divergence;
  }
  return { calculateDivergenceScore };
})();
