/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeDeviationAndGenerateProposal exports=analyzeDeviationAndGenerateProposal */
const __aivicBundle_41_analyzeDeviationAndGenerateProposal = (() => {
  function analyzeDeviationAndGenerateProposal(input: any): any {
    // Input validation: Check if actualDemand exists and is not empty
    if (!input.actualDemand || input.actualDemand.length === 0) {
      console.error('実績データが存在しません');
      return {
        success: false,
        errorCode: 'NO_ACTUAL_DEMAND_DATA',
        deviation: null,
        proposals: []
      };
    }
  
    // Input validation: Check if actualDemand is complete (all forecasted categories have actual data)
    const forecastedCategories = new Set(
      input.forecastedDemand.map((item: any) => item.category)
    );
    const actualCategories = new Set(
      input.actualDemand.map((item: any) => item.category)
    );
  
    const missingCategories = Array.from(forecastedCategories).filter(
      (cat) => !actualCategories.has(cat)
    );
  
    if (missingCategories.length > 0) {
      console.error('実績データが不完全です。欠落カテゴリ: ' + missingCategories.join(', '));
      return {
        success: false,
        errorCode: 'INCOMPLETE_ACTUAL_DEMAND_DATA',
        deviation: null,
        proposals: []
      };
    }
  
    // Calculate deviations for each forecasted item
    const deviations: number[] = [];
  
    for (const forecastItem of input.forecastedDemand) {
      const actualItem = input.actualDemand.find(
        (item: any) => item.category === forecastItem.category
      );
  
      if (actualItem) {
        const deviation = Math.abs(forecastItem.forecastQty - actualItem.actualQty);
        deviations.push(deviation);
      }
    }
  
    // Calculate statistics
    const avgDeviation =
      deviations.length > 0
        ? deviations.reduce((sum, d) => sum + d, 0) / deviations.length
        : 0;
    const maxDeviation = deviations.length > 0 ? Math.max(...deviations) : 0;
    const minDeviation = deviations.length > 0 ? Math.min(...deviations) : 0;
  
    // Generate proposals based on deviation analysis
    const proposals: Array<{ proposal: string; rationale: string; priority: number }> = [];
  
    if (avgDeviation > 0) {
      // Analyze which categories have the highest deviations
      const categoryDeviations = input.forecastedDemand.map((forecastItem: any) => {
        const actualItem = input.actualDemand.find(
          (item: any) => item.category === forecastItem.category
        );
        return {
          category: forecastItem.category,
          deviation: actualItem
            ? Math.abs(forecastItem.forecastQty - actualItem.actualQty)
            : 0
        };
      });
  
      categoryDeviations.sort((a: any, b: any) => b.deviation - a.deviation);
  
      // Generate proposal for top deviation category
      if (categoryDeviations[0].deviation > 0) {
        proposals.push({
          proposal: `${categoryDeviations[0].category}の需要予測精度を向上させるため、過去の需要パターンを再分析してください`,
          rationale: `${categoryDeviations[0].category}の乖離が最大（${categoryDeviations[0].deviation}）であり、予測モデルの改善が必要`,
          priority: 1
        });
      }
    }
  
    return {
      success: true,
      deviationAnalysis: {
        avgDeviation,
        maxDeviation,
        minDeviation
      },
      proposals
    };
  }
  return { analyzeDeviationAndGenerateProposal };
})();
