/* AIVIC_FUNCTION_BUNDLE_START owner=calculateCorrelationCoefficient exports=calculateCorrelationCoefficient */
const __aivicBundle_44_calculateCorrelationCoefficient = (() => {
  interface CalculateCorrelationCoefficientInput {
    primary_values: number[];
    external_values: number[];
  }
  
   function calculateCorrelationCoefficient(
    input: CalculateCorrelationCoefficientInput
  ): number {
    const { primary_values, external_values } = input;
  
    if (
      !primary_values ||
      !external_values ||
      primary_values.length === 0 ||
      external_values.length === 0 ||
      primary_values.length !== external_values.length
    ) {
      return 0;
    }
  
    const n = primary_values.length;
  
    const meanPrimary =
      primary_values.reduce((sum, val) => sum + val, 0) / n;
    const meanExternal =
      external_values.reduce((sum, val) => sum + val, 0) / n;
  
    let numerator = 0;
    let sumSqPrimary = 0;
    let sumSqExternal = 0;
  
    for (let i = 0; i < n; i++) {
      const diffPrimary = primary_values[i] - meanPrimary;
      const diffExternal = external_values[i] - meanExternal;
  
      numerator += diffPrimary * diffExternal;
      sumSqPrimary += diffPrimary * diffPrimary;
      sumSqExternal += diffExternal * diffExternal;
    }
  
    const denominator = Math.sqrt(sumSqPrimary * sumSqExternal);
  
    if (denominator === 0) {
      return 0;
    }
  
    const correlationCoefficient = numerator / denominator;
  
    return Math.max(-1, Math.min(1, correlationCoefficient));
  }
  return { calculateCorrelationCoefficient };
})();
