/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateWeeklyMealGenerationReport exports=aggregateWeeklyMealGenerationReport */
const __aivicBundle_49_aggregateWeeklyMealGenerationReport = (() => {
  function aggregateWeeklyMealGenerationReport(input: {
    userId: string;
    weekIdentifier: string;
    mealRecords?: Array<{
      mealId: string;
      mealDate: Date;
      dishes: Array<string>;
      totalCalories: number;
      totalProteinGrams: number;
      totalFiberGrams: number;
    }>;
    familyEvaluations?: Array<{
      mealId: string;
      evaluatorId: string;
      satisfactionScore: number;
      completionRate: number;
    }>;
  }): any {
    const { userId, weekIdentifier, mealRecords = [], familyEvaluations = [] } = input;
  
    // Validate week identifier format (ISO 8601 week format: YYYY-Www)
    const weekPattern = /^\d{4}-W\d{2}$/;
    if (!weekPattern.test(weekIdentifier)) {
      return {
        error: true,
        errorCode: '400',
        errorMessage: '週のデータが見つかりません',
        errorLog: `Invalid week identifier format: ${weekIdentifier}`,
      };
    }
  
    // Check if data exists for the week
    if (mealRecords.length === 0 && familyEvaluations.length === 0) {
      return {
        error: true,
        errorCode: '404',
        errorMessage: 'データが見つかりません',
        errorLog: `No meal records or family evaluations found for week ${weekIdentifier} and user ${userId}`,
      };
    }
  
    // If mealRecords is empty but familyEvaluations exist, still treat as no data
    if (mealRecords.length === 0) {
      return {
        error: true,
        errorCode: '404',
        errorMessage: 'データが見つかりません',
        errorLog: `No meal records found for week ${weekIdentifier}`,
      };
    }
  
    // Calculate aggregated metrics
    const totalMealsGenerated = mealRecords.length;
  
    const totalCalories = mealRecords.reduce((sum, meal) => sum + meal.totalCalories, 0);
    const avgCaloriesPerMeal = totalMealsGenerated > 0 ? totalCalories / totalMealsGenerated : 0;
  
    const totalProtein = mealRecords.reduce((sum, meal) => sum + meal.totalProteinGrams, 0);
    const avgProteinPerMeal = totalMealsGenerated > 0 ? totalProtein / totalMealsGenerated : 0;
  
    const totalFiber = mealRecords.reduce((sum, meal) => sum + meal.totalFiberGrams, 0);
    const avgFiberPerMeal = totalMealsGenerated > 0 ? totalFiber / totalMealsGenerated : 0;
  
    // Calculate family satisfaction and completion rates
    let avgFamilySatisfaction = 0;
    let avgCompletionRate = 0;
    let mealsWithFullCompletion = 0;
    let mealsWithPartialCompletion = 0;
  
    if (familyEvaluations.length > 0) {
      const totalSatisfaction = familyEvaluations.reduce(
        (sum, evaluation) => sum + evaluation.satisfactionScore,
        0
      );
      avgFamilySatisfaction = totalSatisfaction / familyEvaluations.length;
  
      const totalCompletion = familyEvaluations.reduce(
        (sum, evaluation) => sum + evaluation.completionRate,
        0
      );
      avgCompletionRate = totalCompletion / familyEvaluations.length;
  
      // Count meals by completion rate
      familyEvaluations.forEach((evaluation) => {
        if (evaluation.completionRate === 100) {
          mealsWithFullCompletion++;
        } else if (evaluation.completionRate > 0 && evaluation.completionRate < 100) {
          mealsWithPartialCompletion++;
        }
      });
    }
  
    return {
      weekStartDate: new Date(weekIdentifier),
      totalMealsGenerated,
      avgCaloriesPerMeal,
      avgProteinPerMeal,
      avgFiberPerMeal,
      avgFamilySatisfaction,
      avgCompletionRate,
      mealsWithFullCompletion,
      mealsWithPartialCompletion,
    };
  }
  return { aggregateWeeklyMealGenerationReport };
})();
