/* AIVIC_FUNCTION_BUNDLE_START owner=generateWeeklyMealReport exports=generateWeeklyMealReport */
const __aivicBundle_50_generateWeeklyMealReport = (() => {
  function generateWeeklyMealReport(input: {
    userId: string;
    weekStartDate: Date;
    weekEndDate?: Date;
    mealsGenerated: number;
    mealsAccepted: number;
    mealRejections: number;
    averageCookingTimeMinutes: number;
    satisfactionScore: number;
    previousWeekData?: { avgSatisfaction?: number; avgCookingTimeReduction?: number } | null;
  }): {
    weeklySuccessRate: number;
    previousWeekComparisonRate: number;
    reportFormat: {
      weekStartDate: string;
      weekEndDate: string;
      successRate: string;
      previousWeekComparison: string;
      averageCookingTime: string;
      satisfactionScore: string;
      rejectionCount: number;
      acceptanceCount: number;
    };
    isPreviousWeekDataAvailable: boolean;
    isNormalComparison: boolean;
    hasErrors: boolean;
    errorMessages: string[];
    warningMessages: string[];
    processStatus: 'completed' | 'failed' | 'partial';
    generatedAt: Date;
  } {
    const errors: string[] = [];
    const warnings: string[] = [];
  
    // Validate required inputs
    if (!input.userId) {
      errors.push('userId is required');
    }
    if (!input.weekStartDate) {
      errors.push('weekStartDate is required');
    }
    if (input.mealsGenerated < 0 || input.mealsAccepted < 0 || input.mealRejections < 0) {
      errors.push('Meal counts cannot be negative');
    }
    if (input.mealsGenerated === 0) {
      errors.push('No meals generated for this week');
    }
  
    const hasErrors = errors.length > 0;
    const processStatus: 'completed' | 'failed' | 'partial' = hasErrors ? 'failed' : 'completed';
  
    // Calculate weekly success rate
    const weeklySuccessRate = input.mealsGenerated > 0
      ? parseFloat(((input.mealsAccepted / input.mealsGenerated) * 100).toFixed(2))
      : 0;
  
    // Determine if previous week data is available
    const isPreviousWeekDataAvailable = input.previousWeekData !== null && input.previousWeekData !== undefined;
  
    // Calculate previous week comparison rate
    let previousWeekComparisonRate = 0;
    let isNormalComparison = false;
  
    if (isPreviousWeekDataAvailable && input.previousWeekData) {
      const prevSuccessRate = input.previousWeekData.avgSatisfaction || 0;
      if (prevSuccessRate > 0) {
        previousWeekComparisonRate = parseFloat(
          (((input.satisfactionScore - prevSuccessRate) / prevSuccessRate) * 100).toFixed(2)
        );
        isNormalComparison = true;
      } else {
        previousWeekComparisonRate = 0;
        isNormalComparison = false;
      }
    } else {
      previousWeekComparisonRate = 0;
      isNormalComparison = false;
    }
  
    // Format dates
    const weekStartDateStr = input.weekStartDate.toISOString().split('T')[0];
    const weekEndDate = input.weekEndDate || new Date(input.weekStartDate.getTime() + 6 * 24 * 60 * 60 * 1000);
    const weekEndDateStr = weekEndDate.toISOString().split('T')[0];
  
    // Build report format
    const reportFormat = {
      weekStartDate: weekStartDateStr,
      weekEndDate: weekEndDateStr,
      successRate: `${weeklySuccessRate}%`,
      previousWeekComparison: `${previousWeekComparisonRate}%`,
      averageCookingTime: `${input.averageCookingTimeMinutes} min`,
      satisfactionScore: `${input.satisfactionScore} / 100`,
      rejectionCount: input.mealRejections,
      acceptanceCount: input.mealsAccepted,
    };
  
    return {
      weeklySuccessRate,
      previousWeekComparisonRate,
      reportFormat,
      isPreviousWeekDataAvailable,
      isNormalComparison,
      hasErrors,
      errorMessages: errors,
      warningMessages: warnings,
      processStatus,
      generatedAt: new Date(),
    };
  }
  return { generateWeeklyMealReport };
})();
