const __aivicBundle_51_aggregateMonthlyCostReduction = (() => {
  interface AggregateMonthlyCostReductionInput {
    purchase_records?: Array<{
      purchase_id?: string;
      purchase_date: string;
      food_category?: string;
      unit_price?: number;
      quantity?: number;
      total_amount?: number;
      satisfaction_score: number;
    }>;
    monthly_budget: number;
    target_month: string;
  }
  
  interface AggregateMonthlyCostReductionOutput {
    monthly_expense_total: number;
    budget_reduction_rate: number;
    cost_by_category: Record<string, number>;
    average_satisfaction_score: number;
    aggregation_month: string;
  }
  
   function aggregateMonthlyCostReduction(
    input: AggregateMonthlyCostReductionInput
  ): AggregateMonthlyCostReductionOutput {
    const { purchase_records = [], monthly_budget, target_month } = input;
  
    // フィルタリング: target_month に該当する購入記録のみを抽出
    const filteredRecords = purchase_records.filter((record) => {
      const recordDate = new Date(record.purchase_date);
      const recordYearMonth = `${recordDate.getUTCFullYear()}-${String(
        recordDate.getUTCMonth() + 1
      ).padStart(2, "0")}`;
      return recordYearMonth === target_month;
    });
  
    // 月次食費実績の計算
    const monthly_expense_total = filteredRecords.reduce(
      (sum, record) => sum + (record.total_amount || 0),
      0
    );
  
    // 予算比削減率の計算: (予算 - 実績) / 予算 × 100
    const budget_reduction_rate =
      monthly_budget > 0
        ? ((monthly_budget - monthly_expense_total) / monthly_budget) * 100
        : 0;
  
    // 食材別コストの集計
    const cost_by_category: Record<string, number> = {};
    filteredRecords.forEach((record) => {
      const category = record.food_category || "その他";
      cost_by_category[category] =
        (cost_by_category[category] || 0) + (record.total_amount || 0);
    });
  
    // 満足度スコアの平均計算
    const average_satisfaction_score =
      filteredRecords.length > 0
        ? filteredRecords.reduce((sum, record) => sum + record.satisfaction_score, 0) /
          filteredRecords.length
        : 0;
  
    return {
      monthly_expense_total,
      budget_reduction_rate,
      cost_by_category,
      average_satisfaction_score,
      aggregation_month: target_month,
    };
  }
  return { aggregateMonthlyCostReduction };
})();
