/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMonthlyCostReductionEffect exports=calculateMonthlyCostReductionEffect */
const __aivicBundle_53_calculateMonthlyCostReductionEffect = (() => {
  function calculateMonthlyCostReductionEffect(input: {
    budget_amount: number;
    actual_amount: number;
  }): {
    reduction_rate: number;
    reduction_amount: number;
    is_over_budget: boolean;
  } {
    const { budget_amount, actual_amount } = input;
  
    if (budget_amount <= 0) {
      throw new Error('予算額は0より大きい値である必要があります');
    }
  
    if (actual_amount < 0) {
      throw new Error('実績額は0以上である必要があります');
    }
  
    const reduction_amount = budget_amount - actual_amount;
    const reduction_rate = (reduction_amount / budget_amount) * 100;
    const is_over_budget = actual_amount > budget_amount;
  
    return {
      reduction_rate,
      reduction_amount,
      is_over_budget,
    };
  }
  return { calculateMonthlyCostReductionEffect };
})();
