/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutrientAchievementScore exports=calculateNutrientAchievementScore */
const __aivicBundle_55_calculateNutrientAchievementScore = (() => {
  function calculateNutrientAchievementScore(input: {
    user_id?: string;
    analysis_month?: string;
    meal_evaluation_records?: any[];
    nutrientType?: string;
    targetAmount?: number;
    actualAmount?: number;
    unit?: string;
    healthImportance?: 'critical' | 'high' | 'medium' | 'low';
  }): {
    nutrientType: string;
    targetAmount: number;
    actualAmount: number;
    achievementRate: number;
    status: 'achieved' | 'partial' | 'insufficient';
    gap: number;
    gapPercentage: number;
    healthRiskLevel: 'none' | 'low' | 'medium' | 'high';
    recommendedAction: string;
  } {
    // Handle meal evaluation records input format (from test)
    if (input.meal_evaluation_records !== undefined) {
      if (!Array.isArray(input.meal_evaluation_records) || input.meal_evaluation_records.length === 0) {
        throw new Error('食事評価データが存在しません');
      }
    }
  
    // Handle nutrient achievement score calculation format
    const nutrientType = input.nutrientType || 'unknown';
    const targetAmount = input.targetAmount ?? 0;
    const actualAmount = input.actualAmount ?? 0;
    
    const healthImportance = input.healthImportance || 'medium';
  
    // Calculate achievement rate
    const achievementRate = targetAmount > 0 ? (actualAmount / targetAmount) * 100 : 0;
  
    // Calculate gap
    const gap = Math.max(0, targetAmount - actualAmount);
    const gapPercentage = targetAmount > 0 ? (gap / targetAmount) * 100 : 0;
  
    // Determine status
    let status: 'achieved' | 'partial' | 'insufficient';
    if (achievementRate >= 100) {
      status = 'achieved';
    } else if (achievementRate >= 75) {
      status = 'partial';
    } else {
      status = 'insufficient';
    }
  
    // Determine health risk level based on achievement rate and importance
    let healthRiskLevel: 'none' | 'low' | 'medium' | 'high';
    if (achievementRate >= 100) {
      healthRiskLevel = 'none';
    } else if (achievementRate >= 75) {
      healthRiskLevel = 'low';
    } else if (achievementRate >= 50) {
      if (healthImportance === 'critical') {
        healthRiskLevel = 'high';
      } else if (healthImportance === 'high') {
        healthRiskLevel = 'medium';
      } else {
        healthRiskLevel = 'low';
      }
    } else {
      healthRiskLevel = healthImportance === 'critical' ? 'high' : 'medium';
    }
  
    // Generate recommended action
    let recommendedAction = '';
    if (status === 'achieved') {
      recommendedAction = `${nutrientType}の摂取目標を達成しています。現在の食生活を継続してください`;
    } else if (status === 'partial') {
      recommendedAction = `${nutrientType}をさらに増やすことをお勧めします。関連食材を献立に追加してください`;
    } else {
      if (nutrientType === 'protein') {
        recommendedAction = 'タンパク質を含む食材を献立に追加してください';
      } else if (nutrientType === 'calcium') {
        recommendedAction = 'カルシウム豊富な食材（乳製品、小魚など）を毎日の献立に組み込んでください';
      } else if (nutrientType === 'fiber') {
        recommendedAction = '食物繊維を含む野菜や穀物を毎日の食事に取り入れてください';
      } else if (nutrientType === 'iron') {
        recommendedAction = '鉄分を含む食材（赤身肉、ほうれん草など）を献立に追加してください';
      } else {
        recommendedAction = `${nutrientType}の摂取量を増やすために、関連食材を献立に組み込んでください`;
      }
    }
  
    return {
      nutrientType,
      targetAmount,
      actualAmount,
      achievementRate: Math.round(achievementRate * 100) / 100,
      status,
      gap: Math.round(gap * 100) / 100,
      gapPercentage: Math.round(gapPercentage * 100) / 100,
      healthRiskLevel,
      recommendedAction,
    };
  }
  return { calculateNutrientAchievementScore };
})();
