/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionAchievementScore exports=calculateNutritionAchievementScore */
const __aivicBundle_56_calculateNutritionAchievementScore = (() => {
  interface CalculateNutritionAchievementScoreResult {
    itemScores: Record<string, number>;
    excludedItems: string[];
    overallScore: number;
    hasError: boolean;
    errorMessage: string | null;
  }
  
   function calculateNutritionAchievementScore(
    nutritionTargets: Record<string, number>,
    nutritionActuals: Record<string, number>
  ): CalculateNutritionAchievementScoreResult {
    const itemScores: Record<string, number> = {};
    const excludedItems: string[] = [];
    let hasError = false;
    let errorMessage: string | null = null;
  
    // Validate inputs
    if (!nutritionTargets || typeof nutritionTargets !== 'object') {
      return {
        itemScores: {},
        excludedItems: [],
        overallScore: 0,
        hasError: true,
        errorMessage: '栄養目標値が設定されていません',
      };
    }
  
    if (!nutritionActuals || typeof nutritionActuals !== 'object') {
      return {
        itemScores: {},
        excludedItems: [],
        overallScore: 0,
        hasError: true,
        errorMessage: '栄養実績値が設定されていません',
      };
    }
  
    // Get all nutrient keys from targets
    const nutrientKeys = Object.keys(nutritionTargets);
  
    if (nutrientKeys.length === 0) {
      return {
        itemScores: {},
        excludedItems: [],
        overallScore: 0,
        hasError: true,
        errorMessage: '栄養基準が設定されていません',
      };
    }
  
    // Calculate achievement score for each nutrient
    for (const nutrient of nutrientKeys) {
      const target = nutritionTargets[nutrient];
      const actual = nutritionActuals[nutrient] ?? 0;
  
      // Exclude items with zero target value
      if (target === 0) {
        excludedItems.push(nutrient);
        continue;
      }
  
      // Calculate achievement percentage (actual / target * 100)
      const achievementPercent = (actual / target) * 100;
  
      // Clamp score to 0-100 range
      const score = Math.min(Math.max(achievementPercent, 0), 100);
      itemScores[nutrient] = score;
    }
  
    // Calculate overall score as average of all item scores
    const scoreValues = Object.values(itemScores);
    const overallScore =
      scoreValues.length > 0
        ? scoreValues.reduce((sum, score) => sum + score, 0) / scoreValues.length
        : 0;
  
    return {
      itemScores,
      excludedItems,
      overallScore: Math.round(overallScore * 100) / 100,
      hasError,
      errorMessage,
    };
  }
  return { calculateNutritionAchievementScore };
})();
export const calculateNutritionAchievementScore = __aivicBundle_56_calculateNutritionAchievementScore.calculateNutritionAchievementScore;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateNutritionAchievementScore */

/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyFoodCostOverage exports=analyzeMonthlyFoodCostOverage */
const __aivicBundle_57_analyzeMonthlyFoodCostOverage = (() => {
  interface AnalyzeMonthlyFoodCostOverageInput {
    analysis_month: string;
    previous_month: string;
    current_month_budget: number;
    current_month_actual: number;
    previous_month_actual: number;
    category_compositions: Array<{
      category: string;
      dishes_count_previous: number;
      dishes_count_current: number;
      avg_price_previous: number;
      avg_price_current: number;
    }>;
  }
  
  interface CategoryBreakdownItem {
    category: string;
    composition_increase: number;
    price_variation_increase: number;
    total_increase: number;
    dishes_count_previous: number;
    dishes_count_current: number;
    avg_price_previous: number;
    avg_price_current: number;
    price_change_rate: number;
  }
  
  interface AnalyzeMonthlyFoodCostOverageResult {
    analysis_month: string;
    total_overage_amount: number;
    category_breakdown: CategoryBreakdownItem[];
    composition_factor_total: number;
    price_factor_total: number;
  }
  
   function analyzeMonthlyFoodCostOverage(
    input: AnalyzeMonthlyFoodCostOverageInput
  ): AnalyzeMonthlyFoodCostOverageResult {
    const {
      analysis_month,
      current_month_budget,
      current_month_actual,
      category_compositions,
    } = input;
  
    // 当月実績と予算の差分を超過額とする
    const total_overage_amount = Math.max(0, current_month_actual - current_month_budget);
  
    // カテゴリ別の分解を計算
    const category_breakdown: CategoryBreakdownItem[] = category_compositions.map(
      (comp) => {
        // 献立構成による増加: (当月料理数 - 前月料理数) × 前月平均単価
        const composition_increase =
          Math.max(0, comp.dishes_count_current - comp.dishes_count_previous) *
          comp.avg_price_previous;
  
        // 単価変動による増加: 前月料理数 × (当月平均単価 - 前月平均単価)
        const price_variation_increase =
          Math.max(0, comp.avg_price_current - comp.avg_price_previous) *
          comp.dishes_count_previous;
  
        // 総増加額
        const total_increase = composition_increase + price_variation_increase;
  
        // 単価変動率（パーセンテージ、小数第2位まで）
        const price_change_rate =
          comp.avg_price_previous > 0
            ? Math.round(
                ((comp.avg_price_current - comp.avg_price_previous) /
                  comp.avg_price_previous) *
                  100 *
                  100
              ) / 100
            : 0;
  
        return {
          category: comp.category,
          composition_increase,
          price_variation_increase,
          total_increase,
          dishes_count_previous: comp.dishes_count_previous,
          dishes_count_current: comp.dishes_count_current,
          avg_price_previous: comp.avg_price_previous,
          avg_price_current: comp.avg_price_current,
          price_change_rate,
        };
      }
    );
  
    // 献立構成要因の合計
    const composition_factor_total = category_breakdown.reduce(
      (sum, cat) => sum + cat.composition_increase,
      0
    );
  
    // 単価変動要因の合計
    const price_factor_total = category_breakdown.reduce(
      (sum, cat) => sum + cat.price_variation_increase,
      0
    );
  
    return {
      analysis_month,
      total_overage_amount,
      category_breakdown,
      composition_factor_total,
      price_factor_total,
    };
  }
  return { analyzeMonthlyFoodCostOverage };
})();
export const analyzeMonthlyFoodCostOverage = __aivicBundle_57_analyzeMonthlyFoodCostOverage.analyzeMonthlyFoodCostOverage;
