const __aivicBundle_58_analyzeExcessSpendingFactors = (() => {
  function analyzeExcessSpendingFactors(input: {
    budget_amount: number;
    actual_expense: number;
    expense_breakdown: Array<{ category: string; amount: number }>;
  }): {
    excess_amount: number;
    excess_factors: Array<{ factor: string; impact: number }>;
    excess_rate: number;
    analysis_status: string;
  } {
    const { budget_amount, actual_expense, expense_breakdown } = input;
  
    const excess_amount = Math.max(0, actual_expense - budget_amount);
    const excess_rate =
      budget_amount > 0 ? (excess_amount / budget_amount) * 100 : 0;
  
    if (excess_amount === 0) {
      return {
        excess_amount: 0,
        excess_factors: [],
        excess_rate: 0,
        analysis_status: 'NO_EXCESS',
      };
    }
  
    const excess_factors: Array<{ factor: string; impact: number }> =
      expense_breakdown
        .map((item) => ({
          factor: item.category,
          impact: item.amount,
        }))
        .sort((a, b) => b.impact - a.impact);
  
    return {
      excess_amount,
      excess_factors,
      excess_rate,
      analysis_status: 'EXCESS_DETECTED',
    };
  }
  return { analyzeExcessSpendingFactors };
})();
