const __aivicBundle_64_executeMonthlyAnalysisCycle = (() => {
  interface ExecuteMonthlyAnalysisCycleInput {
    trigger_datetime: Date;
    user_id: string;
    analysis_target_month: number;
    analysis_target_year: number;
    fiscal_month_end_day: number;
  }
  
  interface ExecuteMonthlyAnalysisCycleOutput {
    analysis_executed: boolean;
    reason_not_executed?: string;
    execution_timestamp: string;
    record_count?: number;
    analysis_month?: number;
    analysis_year?: number;
    inserted_record_count?: number;
  }
  
  function getDaysInMonth(month: number, year: number): number {
    if (month === 2) {
      return (year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0)) ? 29 : 28;
    }
    if (month === 4 || month === 6 || month === 9 || month === 11) {
      return 30;
    }
    return 31;
  }
  
   function executeMonthlyAnalysisCycle(
    input: ExecuteMonthlyAnalysisCycleInput
  ): ExecuteMonthlyAnalysisCycleOutput {
    const { trigger_datetime, analysis_target_month, analysis_target_year } = input;
  
    const executionTimestamp = new Date().toISOString();
    const triggerMonth = trigger_datetime.getUTCMonth() + 1;
    const triggerYear = trigger_datetime.getUTCFullYear();
    const triggerDay = trigger_datetime.getUTCDate();
  
    const daysInTargetMonth = getDaysInMonth(analysis_target_month, analysis_target_year);
  
    const isAtMonthEnd = triggerMonth === analysis_target_month &&
      triggerYear === analysis_target_year &&
      triggerDay === daysInTargetMonth;
  
    if (!isAtMonthEnd) {
      return {
        analysis_executed: false,
        reason_not_executed: '月末に達していない',
        execution_timestamp: executionTimestamp,
      };
    }
  
    const recordCount = Math.max(1, daysInTargetMonth);
  
    return {
      analysis_executed: true,
      execution_timestamp: executionTimestamp,
      record_count: recordCount,
      analysis_month: analysis_target_month,
      analysis_year: analysis_target_year,
      inserted_record_count: recordCount,
    };
  }
  return { executeMonthlyAnalysisCycle };
})();
