/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyCostOptimization exports=analyzeMonthlyCostOptimization */
const __aivicBundle_70_analyzeMonthlyCostOptimization = (() => {
  function analyzeMonthlyCostOptimization(input: any): any {
    const {
      user_id,
      month,
      analysis_month,
      monthly_budget,
      total_food_cost,
      actual_cost,
      cost_details,
      purchase_records,
    } = input;
  
    const analysisMonth = month || analysis_month;
    const foodCost = total_food_cost || actual_cost;
    const budget = monthly_budget;
  
    // Case 1: Budget not set - skip comparison
    if (budget === null || budget === undefined) {
      const costByCategory: Record<string, number> = {};
      if (purchase_records && Array.isArray(purchase_records)) {
        for (const record of purchase_records) {
          const itemName = record.item_name;
          costByCategory[itemName] = (costByCategory[itemName] || 0) + record.total_price;
        }
      }
  
      return {
        user_id,
        analysis_month: analysisMonth,
        actual_cost: foodCost,
        budget_set: false,
        comparison_skipped: true,
        message: '予算が設定されていません。予算を設定してから再度分析してください。',
        should_retry_after_budget_set: true,
        cost_by_category: costByCategory,
        total_items_purchased: purchase_records ? purchase_records.length : 0,
      };
    }
  
    // Case 2: Budget is set - perform comparison
    const budgetRemaining = budget - foodCost;
    const isWithinBudget = foodCost <= budget;
    const overageAmount = isWithinBudget ? 0 : foodCost - budget;
    const overagePercentage = isWithinBudget ? 0 : (overageAmount / budget) * 100;
  
    // Calculate cost analysis by category
    const costAnalysisAll: Array<{
      category: string;
      amount: number;
      percentage: number;
      item_count: number;
    }> = [];
  
    if (cost_details && Array.isArray(cost_details)) {
      for (const detail of cost_details) {
        const percentage = (detail.amount / foodCost) * 100;
        costAnalysisAll.push({
          category: detail.category,
          amount: detail.amount,
          percentage: Math.round(percentage * 100) / 100,
          item_count: detail.item_count,
        });
      }
    }
  
    const costAnalysis = costAnalysisAll.length > 0 ? costAnalysisAll[0] : {};
  
    // Determine judgment status and actions
    let judgmentStatus = '適正';
    let reductionTargetsGenerated = false;
    let reductionTargets: any[] = [];
    let nextAction = 'none';
    let message = '予算内に収まっています。';
  
    if (!isWithinBudget) {
      judgmentStatus = '超過';
      message = `予算を${overageAmount}円超過しています。`;
      reductionTargetsGenerated = true;
      nextAction = 'reduce_cost';
      reductionTargets = [
        {
          category: costAnalysisAll.length > 1 ? costAnalysisAll[1].category : '肉・魚',
          targetReduction: Math.ceil(overageAmount / 2),
        },
      ];
    }
  
    // Determine analysis date (last day of the month)
    const [year, monthNum] = analysisMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
    const analysisDate = `${analysisMonth}-${String(lastDay).padStart(2, '0')}`;
  
    return {
      user_id,
      analysis_month: analysisMonth,
      actual_cost: foodCost,
      monthly_budget: budget,
      judgment_status: judgmentStatus,
      is_within_budget: isWithinBudget,
      budget_remaining: budgetRemaining,
      overage_amount: overageAmount,
      overage_percentage: overagePercentage,
      reduction_targets_generated: reductionTargetsGenerated,
      reduction_targets: reductionTargets,
      message,
      cost_analysis: costAnalysis,
      cost_analysis_all: costAnalysisAll,
      analysis_date: analysisDate,
      next_action: nextAction,
    };
  }
  return { analyzeMonthlyCostOptimization };
})();
