/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMonthlyOptimization exports=calculateMonthlyOptimization */
const __aivicBundle_71_calculateMonthlyOptimization = (() => {
  function calculateMonthlyOptimization(input: {
    monthly_budget?: number;
    actual_expense?: number;
    monthlyActualCost?: number;
    monthlyBudget?: number;
    mealPlanData?: Array<{
      mealId: string;
      ingredients: Array<{ name: string; unitPrice: number; quantity: number }>;
    }>;
    priceFluctuationData?: Array<{
      ingredientName: string;
      basePrice: number;
      actualPrice: number;
      date: string;
    }>;
  }): any {
    const monthlyBudget = input.monthly_budget ?? input.monthlyBudget ?? 0;
    const actualExpense = input.actual_expense ?? input.monthlyActualCost ?? 0;
  
    const excessAmount = Math.max(0, actualExpense - monthlyBudget);
    const excessRate =
      monthlyBudget > 0 ? (excessAmount / monthlyBudget) * 100 : 0;
    const reductionTarget = Math.ceil(excessAmount * 0.8);
  
    const costStatus =
      actualExpense > monthlyBudget ? "over_budget" : "within_budget";
  
    // Calculate high price ingredients from mealPlanData and priceFluctuationData
    const highPriceIngredients: Array<{
      name: string;
      usageCount: number;
      totalCost: number;
      priceIncreaseRate: number;
    }> = [];
  
    if (input.mealPlanData && input.priceFluctuationData) {
      const ingredientCostMap: Record<
        string,
        { totalCost: number; usageCount: number; basePrice: number }
      > = {};
  
      // Aggregate ingredient costs from meal plans
      for (const meal of input.mealPlanData) {
        for (const ingredient of meal.ingredients) {
          if (!ingredientCostMap[ingredient.name]) {
            ingredientCostMap[ingredient.name] = {
              totalCost: 0,
              usageCount: 0,
              basePrice: 0,
            };
          }
          const cost = ingredient.unitPrice * ingredient.quantity;
          ingredientCostMap[ingredient.name].totalCost += cost;
          ingredientCostMap[ingredient.name].usageCount += 1;
        }
      }
  
      // Match with price fluctuation data and calculate increase rate
      for (const fluctuation of input.priceFluctuationData) {
        if (ingredientCostMap[fluctuation.ingredientName]) {
          const entry = ingredientCostMap[fluctuation.ingredientName];
          entry.basePrice = fluctuation.basePrice;
  
          const priceIncreaseRate =
            fluctuation.basePrice > 0
              ? ((fluctuation.actualPrice - fluctuation.basePrice) /
                  fluctuation.basePrice) *
                100
              : 0;
  
          if (priceIncreaseRate > 0) {
            highPriceIngredients.push({
              name: fluctuation.ingredientName,
              usageCount: entry.usageCount,
              totalCost: entry.totalCost,
              priceIncreaseRate: Math.round(priceIncreaseRate * 100) / 100,
            });
          }
        }
      }
  
      // Sort by total cost descending
      highPriceIngredients.sort((a, b) => b.totalCost - a.totalCost);
    }
  
    // Generate improvement actions
    const improvementActions: Array<{
      action: string;
      estimatedSavings: number;
      priority: "high" | "medium" | "low";
    }> = [];
  
    if (excessAmount > 0) {
      for (const ingredient of highPriceIngredients.slice(0, 3)) {
        const estimatedSavings = Math.round(ingredient.totalCost * 0.25);
        improvementActions.push({
          action: `Replace or reduce ${ingredient.name}`,
          estimatedSavings,
          priority: "high",
        });
      }
    }
  
    // Determine next month meal plan adjustment
    const restrictedIngredients =
      excessAmount > 0
        ? highPriceIngredients.slice(0, 2).map((ing) => ing.name)
        : [];
  
    const budgetPriority = excessAmount > 0 ? "strict" : "flexible";
  
    return {
      excess_amount: excessAmount,
      excess_rate: Math.round(excessRate * 100) / 100,
      reduction_target: reductionTarget,
      display_excess: `${excessAmount}円`,
      display_reduction_target: `${reductionTarget}円`,
      status: costStatus,
      costStatus,
      overageAmount: excessAmount,
      overagePercentage: Math.round(excessRate * 100) / 100,
      reductionTarget,
      highPriceIngredients,
      improvementActions,
      nextMonthMealPlanAdjustment: {
        budgetPriority,
        restrictedIngredients,
        seasonalFocusItems: [],
      },
    };
  }
  return { calculateMonthlyOptimization };
})();
