/* AIVIC_FUNCTION_BUNDLE_START owner=calculateDeviationRate exports=calculateDeviationRate */
const __aivicBundle_76_calculateDeviationRate = (() => {
  function calculateDeviationRate(input: {
    forecast_data: Array<{
      item_id: number;
      forecast_price: number;
      forecast_quantity: number;
    }>;
    actual_data: Array<{
      item_id: number;
      actual_price: number;
      actual_quantity: number;
    }>;
  }): number {
    const { forecast_data, actual_data } = input;
  
    if (!forecast_data || forecast_data.length === 0 || !actual_data || actual_data.length === 0) {
      return 0.0;
    }
  
    let totalForecastedValue = 0;
    let totalActualValue = 0;
  
    for (const forecastItem of forecast_data) {
      totalForecastedValue += forecastItem.forecast_price * forecastItem.forecast_quantity;
    }
  
    for (const actualItem of actual_data) {
      totalActualValue += actualItem.actual_price * actualItem.actual_quantity;
    }
  
    if (totalForecastedValue === 0) {
      return 0.0;
    }
  
    const deviationRate = (totalActualValue - totalForecastedValue) / totalForecastedValue;
    const roundedRate = Math.round(deviationRate * 100) / 100;
  
    return roundedRate;
  }
  return { calculateDeviationRate };
})();
export const calculateDeviationRate = __aivicBundle_76_calculateDeviationRate.calculateDeviationRate;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateDeviationRate */

/* AIVIC_FUNCTION_BUNDLE_START owner=determinePrioritizedImprovementFeatures exports=determinePrioritizedImprovementFeatures */
const __aivicBundle_77_determinePrioritizedImprovementFeatures = (() => {
  interface DeterminePrioritizedImprovementFeaturesInput {
    feature_id: string;
    feature_name: string;
    accuracy_decline_rate: number;
    impact_score: number;
    implementation_difficulty: number;
  }
  
  interface DeterminePrioritizedImprovementFeaturesFeature {
    feature_id: string;
    feature_name: string;
    priority_score: number;
    priority_rank: number;
  }
  
  interface DeterminePrioritizedImprovementFeaturesResult {
    prioritized_features: DeterminePrioritizedImprovementFeaturesFeature[];
    highest_priority_feature: {
      feature_id: string;
      feature_name: string;
      priority_score: number;
    };
    total_features_evaluated: number;
  }
  
   function determinePrioritizedImprovementFeatures(
    input: DeterminePrioritizedImprovementFeaturesInput[] | null
  ): DeterminePrioritizedImprovementFeaturesResult {
    if (!input || !Array.isArray(input) || input.length === 0) {
      throw new Error("改善対象機能が指定されていません");
    }
  
    const featuresWithScores = input.map((feature) => {
      if (feature.implementation_difficulty <= 0) {
        throw new Error(
          "実装難易度は0より大きい値である必要があります"
        );
      }
  
      const priorityScore =
        (feature.accuracy_decline_rate * feature.impact_score) /
        feature.implementation_difficulty;
  
      return {
        feature_id: feature.feature_id,
        feature_name: feature.feature_name,
        priority_score: priorityScore,
        accuracy_decline_rate: feature.accuracy_decline_rate,
        impact_score: feature.impact_score,
      };
    });
  
    const sortedFeatures = featuresWithScores.sort((a, b) => {
      if (b.priority_score !== a.priority_score) {
        return b.priority_score - a.priority_score;
      }
      return b.impact_score - a.impact_score;
    });
  
    const prioritizedFeatures: DeterminePrioritizedImprovementFeaturesFeature[] =
      sortedFeatures.map((feature, index) => ({
        feature_id: feature.feature_id,
        feature_name: feature.feature_name,
        priority_score: feature.priority_score,
        priority_rank: index + 1,
      }));
  
    const highestPriorityFeature = prioritizedFeatures[0];
  
    return {
      prioritized_features: prioritizedFeatures,
      highest_priority_feature: {
        feature_id: highestPriorityFeature.feature_id,
        feature_name: highestPriorityFeature.feature_name,
        priority_score: highestPriorityFeature.priority_score,
      },
      total_features_evaluated: input.length,
    };
  }
  return { determinePrioritizedImprovementFeatures };
})();
export const determinePrioritizedImprovementFeatures: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_77_determinePrioritizedImprovementFeatures.determinePrioritizedImprovementFeatures as (...args: any[]) => any)(...args);
