const __aivicBundle_89_validateMonthlyForecastExecutionTiming = (() => {
  interface ValidateMonthlyForecastExecutionTimingInput {
    current_date: Date;
    analyst_user_id: string;
    previous_month_start: Date;
    previous_month_end: Date;
    forecast_data_count: number;
    actual_data_count: number;
  }
  
  interface ValidateMonthlyForecastExecutionTimingOutput {
    should_execute_verification: boolean;
    execution_status: 'ready' | 'wait';
    message: string;
    timing_valid: boolean;
    data_available: boolean;
    next_action: string;
  }
  
   function validateMonthlyForecastExecutionTiming(
    input: ValidateMonthlyForecastExecutionTimingInput
  ): ValidateMonthlyForecastExecutionTimingOutput {
    // Validation: analyst_user_id must not be empty
    if (!input.analyst_user_id || input.analyst_user_id.trim() === '') {
      throw new Error('ユーザーIDが指定されていません');
    }
  
    // Validation: current_date must be a valid Date
    if (!(input.current_date instanceof Date) || isNaN(input.current_date.getTime())) {
      throw new Error('日付が無効です');
    }
  
    // Validation: forecast_data_count must be non-negative
    if (input.forecast_data_count < 0) {
      throw new Error('予測データ件数が無効です');
    }
  
    // Validation: actual_data_count must be non-negative
    if (input.actual_data_count < 0) {
      throw new Error('実績データ件数が無効です');
    }
  
    // Extract day of month from current_date
    const currentDay = input.current_date.getDate();
  
    // Check if current date is within valid verification period (1st to 5th of month)
    const timingValid = currentDay >= 1 && currentDay <= 5;
  
    // Check if both forecast and actual data are available (count > 0)
    const dataAvailable = input.forecast_data_count > 0 && input.actual_data_count > 0;
  
    // Determine if verification should execute
    const shouldExecuteVerification = timingValid && dataAvailable;
  
    // Determine execution status
    const executionStatus = shouldExecuteVerification ? 'ready' : 'wait';
  
    // Generate appropriate message
    let message = '';
    if (shouldExecuteVerification) {
      message = '前月の需要予測精度検証を実行する準備が整っています';
    } else if (!timingValid) {
      message = '検証実行期間外です。月初1日から5日の間に実行してください';
    } else if (!dataAvailable) {
      message = '予測データまたは実績データが不足しています';
    }
  
    // Determine next action
    const nextAction = shouldExecuteVerification ? 'start_verification' : 'wait_for_valid_period';
  
    return {
      should_execute_verification: shouldExecuteVerification,
      execution_status: executionStatus,
      message: message,
      timing_valid: timingValid,
      data_available: dataAvailable,
      next_action: nextAction
    };
  }
  return { validateMonthlyForecastExecutionTiming };
})();
