/* AIVIC_FUNCTION_BUNDLE_START owner=analyzePredictionAccuracyDeviation exports=analyzePredictionAccuracyDeviation */
const __aivicBundle_93_analyzePredictionAccuracyDeviation = (() => {
  function analyzePredictionAccuracyDeviation(input: {
    categories: Array<{
      categoryId: string;
      categoryName: string;
      budgetAmount: number;
      actualAmount: number;
      deviationThreshold: number;
    }>;
    analysisMonth: string;
  }): {
    analysisMonth: string;
    totalCategoriesAnalyzed: number;
    highestPriorityCategoryCount: number;
    prioritizedCategories: Array<{
      categoryId: string;
      categoryName: string;
      budgetAmount: number;
      actualAmount: number;
      deviationRate: number;
      deviationAmount: number;
      priority: "HIGHEST" | "NORMAL";
      priorityLabel: "最高" | "通常";
      displayOrder: number;
    }>;
  } {
    const { categories, analysisMonth } = input;
  
    const categoryDeviations = categories.map((category) => {
      const deviationAmount = category.actualAmount - category.budgetAmount;
      const deviationRate =
        category.budgetAmount !== 0
          ? Math.abs(deviationAmount) / category.budgetAmount
          : 0;
  
      const isHighestPriority = deviationRate > category.deviationThreshold;
      const priority: "HIGHEST" | "NORMAL" = isHighestPriority ? "HIGHEST" : "NORMAL";
      const priorityLabel: "最高" | "通常" = isHighestPriority ? "最高" : "通常";
  
      return {
        categoryId: category.categoryId,
        categoryName: category.categoryName,
        budgetAmount: category.budgetAmount,
        actualAmount: category.actualAmount,
        deviationRate,
        deviationAmount,
        priority,
        priorityLabel,
      };
    });
  
    const sortedByPriority = categoryDeviations.sort((a, b) => {
      if (a.priority === "HIGHEST" && b.priority !== "HIGHEST") return -1;
      if (a.priority !== "HIGHEST" && b.priority === "HIGHEST") return 1;
      return b.deviationRate - a.deviationRate;
    });
  
    const prioritizedCategories = sortedByPriority.map((cat, index) => ({
      ...cat,
      displayOrder: index + 1,
    }));
  
    const highestPriorityCategoryCount = prioritizedCategories.filter(
      (cat) => cat.priority === "HIGHEST"
    ).length;
  
    return {
      analysisMonth,
      totalCategoriesAnalyzed: categories.length,
      highestPriorityCategoryCount,
      prioritizedCategories,
    };
  }
  return { analyzePredictionAccuracyDeviation };
})();
export const analyzePredictionAccuracyDeviation = __aivicBundle_93_analyzePredictionAccuracyDeviation.analyzePredictionAccuracyDeviation;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzePredictionAccuracyDeviation */

/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeNutritionDeficiencyFactors exports=analyzeNutritionDeficiencyFactors */
const __aivicBundle_94_analyzeNutritionDeficiencyFactors = (() => {
  function analyzeNutritionDeficiencyFactors(request: {
    user_id: string;
    analysis_period_days: number;
    start_date: Date;
    end_date: Date;
    data_type: string;
  }): {
    prioritizedDeficiencies: Array<{
      nutrient: string;
      deficitAmount: number;
      healthImpactScore: number;
      preferenceRisk: number;
      priorityScore: number;
      recommendedAction: string;
    }>;
    implementationRisk: {
      highRiskCount: number;
      mediumRiskCount: number;
    };
  } {
    const REQUIRED_DATA_DAYS = 90;
    const DATA_SUFFICIENCY_THRESHOLD_PERCENT = 50;
  
    if (!String(request.user_id).trim()) {
      throw new Error('user_id is required');
    }
    if (request.start_date === undefined || request.start_date === null) {
      throw new Error('start_date is required');
    }
    if (request.end_date === undefined || request.end_date === null) {
      throw new Error('end_date is required');
    }
    if (!String(request.data_type).trim()) {
      throw new Error('data_type is required');
    }
  
    const current_data_days = request.analysis_period_days;
    const actual_data_sufficiency_percent =
      (current_data_days / REQUIRED_DATA_DAYS) * 100;
  
    if (
      actual_data_sufficiency_percent < DATA_SUFFICIENCY_THRESHOLD_PERCENT
    ) {
      const error = new Error(
        `分析に必要なデータが不足しています。最低でも過去${REQUIRED_DATA_DAYS}日間のデータが必要です。現在のデータ保有期間は${current_data_days}日間です。`
      ) as any;
      error.code = 'ERR_INSUFFICIENT_DATA_457';
      error.required_days = REQUIRED_DATA_DAYS;
      error.actual_days = current_data_days;
      error.sufficiency_percent = actual_data_sufficiency_percent;
      throw error;
    }
  
    return {
      prioritizedDeficiencies: [],
      implementationRisk: {
        highRiskCount: 0,
        mediumRiskCount: 0,
      },
    };
  }
  return { analyzeNutritionDeficiencyFactors };
})();
export const analyzeNutritionDeficiencyFactors = __aivicBundle_94_analyzeNutritionDeficiencyFactors.analyzeNutritionDeficiencyFactors;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeNutritionDeficiencyFactors */

