        const correlationWeight = 0.4;
        const frequencyWeight = 0.3;
        const marketDemandWeight = 0.3;
  
        const marketDemandScore = factor.marketDemandScore ?? 0;
        const priorityScore =
          (factor.correlationScore * correlationWeight +
            (factor.frequency / 10) * frequencyWeight +
            marketDemandScore * marketDemandWeight) *
          100;
  
