/* AIVIC_FUNCTION_BUNDLE_START owner=validateMonthlyForecastCycle exports=validateMonthlyForecastCycle */
const __aivicBundle_105_validateMonthlyForecastCycle = (() => {
  function validateMonthlyForecastCycle(input: {
    month_year: string;
    forecast_data: {
      predicted_demand: (number | null)[];
      category: string;
    };
    actual_data: {
      sales_actual: (number | null)[];
      inventory_change?: (number | null)[];
    };
    timestamp_start: string;
    timestamp_sla_limit_ms?: number;
    processing_delay_ms?: number;
  }): {
    cycle_status: string;
    verification_results: {
      accuracy_rate: number;
      deviation_analysis: Array<{
        period: number;
        forecast: number | null;
        actual: number | null;
        deviation: number | null;
      }>;
    };
  } {
    // Validate required inputs
    if (!input.month_year || String(input.month_year).trim() === '') {
      throw new Error('month_year is required');
    }
    if (!input.timestamp_start || String(input.timestamp_start).trim() === '') {
      throw new Error('timestamp_start is required');
    }
  
    const forecastData = input.forecast_data.predicted_demand;
    const actualData = input.actual_data.sales_actual;
  
    // Calculate data quality rates
    const forecastValidCount = forecastData.filter((v) => v !== null).length;
    const forecastQualityRate = (forecastValidCount / forecastData.length) * 100;
  
    const actualValidCount = actualData.filter((v) => v !== null).length;
    const actualQualityRate = (actualValidCount / actualData.length) * 100;
  
    // Check data quality threshold (70% minimum)
    if (forecastQualityRate < 70 || actualQualityRate < 70) {
      throw new Error(
        `データ品質基準を満たしていません。予測品質: ${forecastQualityRate.toFixed(1)}%, 実績品質: ${actualQualityRate.toFixed(1)}%`
      );
    }
  
    // Check SLA constraint if provided
    if (
      input.timestamp_sla_limit_ms !== undefined &&
      input.processing_delay_ms !== undefined
    ) {
      if (input.processing_delay_ms > input.timestamp_sla_limit_ms) {
        throw new Error(
          `SLA違反: 処理時間 ${input.processing_delay_ms}ms が制限時間 ${input.timestamp_sla_limit_ms}ms を超過しています`
        );
      }
    }
  
    // Calculate deviation analysis
    const deviationAnalysis: Array<{
      period: number;
      forecast: number | null;
      actual: number | null;
      deviation: number | null;
    }> = [];
  
    let totalAbsoluteError = 0;
    let validComparisons = 0;
  
    for (let i = 0; i < Math.min(forecastData.length, actualData.length); i++) {
      const forecast = forecastData[i];
      const actual = actualData[i];
      let deviation: number | null = null;
  
      if (forecast !== null && actual !== null) {
        deviation = Math.abs(forecast - actual);
        totalAbsoluteError += deviation;
        validComparisons++;
      }
  
      deviationAnalysis.push({
        period: i,
        forecast,
        actual,
        deviation,
      });
    }
  
    // Calculate accuracy rate
    const meanAbsoluteError =
      validComparisons > 0 ? totalAbsoluteError / validComparisons : 0;
    const accuracyRate = Math.max(0, 100 - (meanAbsoluteError / 200) * 100);
  
    return {
      cycle_status: 'completed',
      verification_results: {
        accuracy_rate: Math.min(100, Math.max(0, accuracyRate)),
        deviation_analysis: deviationAnalysis,
      },
    };
  }
  return { validateMonthlyForecastCycle };
})();
export const validateMonthlyForecastCycle = __aivicBundle_105_validateMonthlyForecastCycle.validateMonthlyForecastCycle;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateMonthlyForecastCycle */

