/* AIVIC_FUNCTION_BUNDLE_START owner=calculateExternalFactorPriorityMatrix exports=calculateExternalFactorPriorityMatrix */
const __aivicBundle_107_calculateExternalFactorPriorityMatrix = (() => {
  interface CalculateExternalFactorPriorityMatrixInput {
    variable_id: string;
    variable_name: string;
    impact_score: number;
    implementation_difficulty_score: number;
  }
  
  interface CalculateExternalFactorPriorityMatrixVariable {
    variable_id: string;
    variable_name: string;
    impact_score: number;
    implementation_difficulty_score: number;
    priority_rank: number;
    quadrant: "high_impact_low_difficulty" | "high_impact_high_difficulty" | "low_impact_low_difficulty" | "low_impact_high_difficulty";
  }
  
  interface CalculateExternalFactorPriorityMatrixResult {
    quadrant_high_impact_low_difficulty: CalculateExternalFactorPriorityMatrixVariable[];
    quadrant_high_impact_high_difficulty: CalculateExternalFactorPriorityMatrixVariable[];
    quadrant_low_impact_low_difficulty: CalculateExternalFactorPriorityMatrixVariable[];
    quadrant_low_impact_high_difficulty: CalculateExternalFactorPriorityMatrixVariable[];
    priority_overall_ranking: CalculateExternalFactorPriorityMatrixVariable[];
  }
  
   function calculateExternalFactorPriorityMatrix(
    variables: CalculateExternalFactorPriorityMatrixInput[]
  ): CalculateExternalFactorPriorityMatrixResult {
    const THRESHOLD = 5.5;
  
    // Classify each variable into quadrants
    const classified = variables.map((variable) => {
      const isHighImpact = variable.impact_score >= THRESHOLD;
      const isLowDifficulty = variable.implementation_difficulty_score < THRESHOLD;
  
      let quadrant: "high_impact_low_difficulty" | "high_impact_high_difficulty" | "low_impact_low_difficulty" | "low_impact_high_difficulty";
  
      if (isHighImpact && isLowDifficulty) {
        quadrant = "high_impact_low_difficulty";
      } else if (isHighImpact && !isLowDifficulty) {
        quadrant = "high_impact_high_difficulty";
      } else if (!isHighImpact && isLowDifficulty) {
        quadrant = "low_impact_low_difficulty";
      } else {
        quadrant = "low_impact_high_difficulty";
      }
  
      return {
        ...variable,
        quadrant,
      };
    });
  
    // Calculate priority score for overall ranking
    const withPriorityScore = classified.map((variable) => {
      const normalizedImpact = variable.impact_score / 10;
      const normalizedDifficulty = variable.implementation_difficulty_score / 10;
      const priorityScore = normalizedImpact - normalizedDifficulty * 0.5;
      return {
        ...variable,
        priorityScore,
      };
    });
  
    // Sort by priority score descending
    const sorted = withPriorityScore.sort((a, b) => b.priorityScore - a.priorityScore);
  
    // Assign priority ranks
    const withRanks = sorted.map((variable, index) => ({
      variable_id: variable.variable_id,
      variable_name: variable.variable_name,
      impact_score: variable.impact_score,
      implementation_difficulty_score: variable.implementation_difficulty_score,
      priority_rank: index + 1,
      quadrant: variable.quadrant,
    }));
  
    // Separate into quadrants
    const quadrantHighImpactLowDifficulty = withRanks.filter(
      (v) => v.quadrant === "high_impact_low_difficulty"
    );
    const quadrantHighImpactHighDifficulty = withRanks.filter(
      (v) => v.quadrant === "high_impact_high_difficulty"
    );
    const quadrantLowImpactLowDifficulty = withRanks.filter(
      (v) => v.quadrant === "low_impact_low_difficulty"
    );
    const quadrantLowImpactHighDifficulty = withRanks.filter(
      (v) => v.quadrant === "low_impact_high_difficulty"
    );
  
    return {
      quadrant_high_impact_low_difficulty: quadrantHighImpactLowDifficulty,
      quadrant_high_impact_high_difficulty: quadrantHighImpactHighDifficulty,
      quadrant_low_impact_low_difficulty: quadrantLowImpactLowDifficulty,
      quadrant_low_impact_high_difficulty: quadrantLowImpactHighDifficulty,
      priority_overall_ranking: withRanks,
    };
  }
  return { calculateExternalFactorPriorityMatrix };
})();
export const calculateExternalFactorPriorityMatrix = __aivicBundle_107_calculateExternalFactorPriorityMatrix.calculateExternalFactorPriorityMatrix;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateExternalFactorPriorityMatrix */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculatePriorityMatrixPlacement exports=calculatePriorityMatrixPlacement */
const __aivicBundle_108_calculatePriorityMatrixPlacement = (() => {
  function calculatePriorityMatrixPlacement(input: any): any {
    // 入力の型チェック
    if (!input) {
      return {
        error_code: 'ERR_INSUFFICIENT_EXTERNAL_DATA',
        error_message: '外部要因分析データが不足しているため、優先度マトリクス配置を実行できません。不足している変数: ',
        priority_matrix: null,
        is_success: false,
        affected_records_count: 0,
      };
    }
  
    // 外部要因データと不足変数の検証
    const externalFactors = input.externalFactors || [];
    const missingVariables = input.missing_variables || [];
    const requiredVariablesCount = 5; // 業務上の必須変数数
  
    // データ不足判定：外部要因データが50%以下、または不足変数が存在する場合
    const dataCompleteness = externalFactors.length / requiredVariablesCount;
    const hasInsufficientData = dataCompleteness <= 0.5 || missingVariables.length > 0;
  
    if (hasInsufficientData) {
      const missingVarList = missingVariables.length > 0 
        ? missingVariables.join(', ')
        : '複数の変数';
      
      const errorMessage = `外部要因分析データが不足しているため、優先度マトリクス配置を実行できません。不足している変数: ${missingVarList}`;
  
      return {
        error_code: 'ERR_INSUFFICIENT_EXTERNAL_DATA',
        error_message: errorMessage,
        priority_matrix: null,
        is_success: false,
        affected_records_count: 0,
      };
    }
  
    // 正常系：優先度マトリクスの配置処理
    const priorityMatrix = input.priorityMatrix || [];
    const developmentResourceAvailability = input.developmentResourceAvailability ?? 50;
    const competitiveImpactPotential = input.competitiveImpactPotential ?? 50;
  
    // 各要因をマトリクスにプロット
    const placementMatrix = priorityMatrix.map((factor: any) => {
      // リソース利用可能度と競合差別化ポテンシャルに基づいてスコアを計算
      const xAxisResourceAvailability = developmentResourceAvailability;
      const yAxisCompetitiveImpact = competitiveImpactPotential;
  
      // 象限判定ロジック
      let quadrant: 'quick_win' | 'strategic' | 'fill_in' | 'low_priority';
      
      if (xAxisResourceAvailability >= 50 && yAxisCompetitiveImpact >= 50) {
        quadrant = 'quick_win'; // リソース高・差別化高
      } else if (xAxisResourceAvailability < 50 && yAxisCompetitiveImpact >= 50) {
        quadrant = 'strategic'; // リソース低・差別化高
      } else if (xAxisResourceAvailability >= 50 && yAxisCompetitiveImpact < 50) {
        quadrant = 'fill_in'; // リソース高・差別化低
      } else {
        quadrant = 'low_priority'; // リソース低・差別化低
      }
  
      return {
        factor_type: factor.factor_type,
        x_axis_resource_availability: xAxisResourceAvailability,
        y_axis_competitive_impact: yAxisCompetitiveImpact,
        quadrant,
      };
    });
  
    // 象限別に実装順序を決定
    const quadrantPriority: Record<string, number> = {
      quick_win: 1,
      strategic: 2,
      fill_in: 3,
      low_priority: 4,
    };
  
    const recommendedImplementationOrder = placementMatrix
      .filter((item: any) => item.quadrant !== 'low_priority')
      .sort((a: any, b: any) => {
        const priorityA = quadrantPriority[a.quadrant];
        const priorityB = quadrantPriority[b.quadrant];
        return priorityA - priorityB;
      })
      .map((item: any, index: number) => ({
        rank: index + 1,
        factor_type: item.factor_type,
        quadrant: item.quadrant,
      }));
  
    return {
      placementMatrix,
      recommendedImplementationOrder,
    };
  }
  return { calculatePriorityMatrixPlacement };
})();
export const calculatePriorityMatrixPlacement = __aivicBundle_108_calculatePriorityMatrixPlacement.calculatePriorityMatrixPlacement;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculatePriorityMatrixPlacement */

/* AIVIC_FUNCTION_BUNDLE_START owner=determinePriorityMatrixPlacement exports=determinePriorityMatrixPlacement */
const __aivicBundle_109_determinePriorityMatrixPlacement = (() => {
  function determinePriorityMatrixPlacement(
    variable_data: {
      variable_id: string;
      variable_name: string;
      impact_score: number;
      implementation_difficulty_score: number;
      correlation_coefficient: number;
      trust_score: number;
    },
    matrix_config: {
      x_axis_min: number;
      x_axis_max: number;
      y_axis_min: number;
      y_axis_max: number;
      center_x: number;
      center_y: number;
    }
  ): {
    position_x: number;
    position_y: number;
    quadrant_classification: string;
    is_center_positioned: boolean;
    distance_from_center: number;
    center_region_offset_x: number;
    center_region_offset_y: number;
    visual_x_pixel_position: number;
    visual_y_pixel_position: number;
    is_within_center_region: boolean;
  } {
    // Validate required inputs
    if (
      variable_data.variable_id === undefined ||
      variable_data.variable_id === null ||
      String(variable_data.variable_id).trim() === ""
    ) {
      throw new Error("variable_id is required");
    }
  
    if (
      variable_data.variable_name === undefined ||
      variable_data.variable_name === null ||
      String(variable_data.variable_name).trim() === ""
    ) {
      throw new Error("variable_name is required");
    }
  
    if (
      variable_data.correlation_coefficient === undefined ||
      variable_data.correlation_coefficient === null
    ) {
      throw new Error("correlation_coefficient is required");
    }
  
    if (
      variable_data.trust_score === undefined ||
      variable_data.trust_score === null
    ) {
      throw new Error("trust_score is required");
    }
  
    if (
      matrix_config.x_axis_min === undefined ||
      matrix_config.x_axis_min === null
    ) {
      throw new Error("x_axis_min is required");
    }
  
    if (
      matrix_config.y_axis_min === undefined ||
      matrix_config.y_axis_min === null
    ) {
      throw new Error("y_axis_min is required");
    }
  
    // Validate impact_score range
    if (
      variable_data.impact_score < 0 ||
      variable_data.impact_score > 100
    ) {
      throw new Error(
        `impact_score must be between 0 and 100, got ${variable_data.impact_score}`
      );
    }
  
    // Validate implementation_difficulty_score range
    if (
      variable_data.implementation_difficulty_score < 0 ||
      variable_data.implementation_difficulty_score > 100
    ) {
      throw new Error(
        `implementation_difficulty_score must be between 0 and 100, got ${variable_data.implementation_difficulty_score}`
      );
    }
  
    // Map impact_score to x-axis position (0-100 scale)
    const position_x = variable_data.impact_score;
  
    // Map implementation_difficulty_score to y-axis position (0-100 scale)
    const position_y = variable_data.implementation_difficulty_score;
  
    // Get center coordinates
    const center_x = matrix_config.center_x;
    const center_y = matrix_config.center_y;
  
    // Calculate distance from center
    const distance_from_center = Math.sqrt(
      Math.pow(position_x - center_x, 2) + Math.pow(position_y - center_y, 2)
    );
  
    // Determine if positioned at center (exact match)
    const is_center_positioned =
      position_x === center_x && position_y === center_y;
  
    // Calculate offsets from center
    const center_region_offset_x = position_x - center_x;
    const center_region_offset_y = position_y - center_y;
  
    // Determine quadrant classification based on position relative to center
    let quadrant_classification: string;
    if (is_center_positioned) {
      quadrant_classification = "center";
    } else if (position_x > center_x && position_y > center_y) {
      quadrant_classification = "high_impact_high_difficulty";
    } else if (position_x > center_x && position_y < center_y) {
      quadrant_classification = "high_impact_low_difficulty";
    } else if (position_x < center_x && position_y > center_y) {
      quadrant_classification = "low_impact_high_difficulty";
    } else {
      quadrant_classification = "low_impact_low_difficulty";
    }
  
    // Calculate visual pixel positions based on axis ranges
    const visual_x_pixel_position =
      (position_x / 100) * matrix_config.x_axis_max;
    const visual_y_pixel_position =
      (position_y / 100) * matrix_config.y_axis_max;
  
    // Determine if within center region (at exact center point)
    const is_within_center_region = is_center_positioned;
  
    return {
      position_x,
      position_y,
      quadrant_classification,
      is_center_positioned,
      distance_from_center,
      center_region_offset_x,
      center_region_offset_y,
      visual_x_pixel_position,
      visual_y_pixel_position,
      is_within_center_region,
    };
  }
  return { determinePriorityMatrixPlacement };
})();
export const determinePriorityMatrixPlacement = __aivicBundle_109_determinePriorityMatrixPlacement.determinePriorityMatrixPlacement;
/* AIVIC_FUNCTION_BUNDLE_END owner=determinePriorityMatrixPlacement */

/* AIVIC_FUNCTION_BUNDLE_START owner=distributeRuleSpecificationAndTrackConfirmation exports=distributeRuleSpecificationAndTrackConfirmation */
const __aivicBundle_110_distributeRuleSpecificationAndTrackConfirmation = (() => {
  interface DistributeRuleSpecificationInput {
    [key: string]: any;
  }
  
  interface ConfirmationTracking {
    member_id: string;
    member_name: string;
    confirmation_status: "confirmed" | "unconfirmed";
    confirmation_timestamp: Date | null;
    view_count: number;
  }
  
  interface ExportTrackingReport {
    distribution_id: string;
    rule_spec_version: string;
    total_recipients: number;
    total_confirmed: number;
    report_generated_timestamp: string;
    member_details: Array<{
      member_id: string;
      member_name: string;
      confirmation_status: "confirmed" | "unconfirmed";
      confirmation_timestamp: Date | null;
    }>;
  }
  
  interface DistributeRuleSpecificationResult {
    [key: string]: any;
  }
  
   function distributeRuleSpecificationAndTrackConfirmation(
    input: DistributeRuleSpecificationInput
  ): DistributeRuleSpecificationResult {
    const {
      distribution_id,
      rule_spec_version,
      rule_spec_content,
      upload_timestamp,
      distribution_target_members,
      scheduled_distribution_time,
      distribution_timing,
      member_confirmations = [],
    } = input;
  
    // Validate required inputs
    if (!String(rule_spec_content).trim()) {
      throw new Error("rule_spec_content is required");
    }
    if (!upload_timestamp) {
      throw new Error("upload_timestamp is required");
    }
    if (!String(distribution_timing).trim()) {
      throw new Error("distribution_timing is required");
    }
  
    // Build confirmation tracking map from member_confirmations
    const confirmationMap = new Map<
      string,
      { confirmation_timestamp: Date; view_count: number }
    >();
    member_confirmations.forEach((conf) => {
      confirmationMap.set(conf.member_id, {
        confirmation_timestamp: conf.confirmation_timestamp,
        view_count: conf.view_count,
      });
    });
  
    // Build confirmation_tracking array
    const confirmation_tracking: ConfirmationTracking[] =
      distribution_target_members.map((member) => {
        const confirmation = confirmationMap.get(member.member_id);
        return {
          member_id: member.member_id,
          member_name: member.name,
          confirmation_status: confirmation ? "confirmed" : "unconfirmed",
          confirmation_timestamp: confirmation?.confirmation_timestamp ?? null,
          view_count: confirmation?.view_count ?? 0,
        };
      });
  
    // Calculate confirmation statistics
    const confirmed_members_count = confirmation_tracking.filter(
      (t) => t.confirmation_status === "confirmed"
    ).length;
    const unconfirmed_members_count = confirmation_tracking.filter(
      (t) => t.confirmation_status === "unconfirmed"
    ).length;
    const confirmation_rate_percentage =
      distribution_target_members.length > 0
        ? Math.round(
            (confirmed_members_count / distribution_target_members.length) * 100
          )
        : 0;
  
    // Build distribution_recipients
    const distribution_recipients = distribution_target_members.map((member) => ({
      member_id: member.member_id,
      member_name: member.name,
      email: member.email,
      role: member.role,
    }));
  
    // Build export_tracking_report
    const export_tracking_report: ExportTrackingReport = {
      distribution_id,
      rule_spec_version,
      total_recipients: distribution_target_members.length,
      total_confirmed: confirmed_members_count,
      report_generated_timestamp: new Date().toISOString(),
      member_details: confirmation_tracking.map((tracking) => ({
        member_id: tracking.member_id,
        member_name: tracking.member_name,
        confirmation_status: tracking.confirmation_status,
        confirmation_timestamp: tracking.confirmation_timestamp,
      })),
    };
  
    return {
      distribution_status: "completed",
      distribution_id,
      rule_spec_version,
      actual_distribution_time: scheduled_distribution_time,
      distributed_to_count: distribution_target_members.length,
      distribution_recipients,
      confirmation_tracking,
      confirmation_rate_percentage,
      confirmed_members_count,
      unconfirmed_members_count,
      export_tracking_report,
    };
  }
  return { distributeRuleSpecificationAndTrackConfirmation };
})();
