/* AIVIC_FUNCTION_BUNDLE_START owner=determineDeploymentApproval exports=determineDeploymentApproval */
const __aivicBundle_113_determineDeploymentApproval = (() => {
  function determineDeploymentApproval(input: {
    functional_test_status?: string;
    performance_test_status?: string;
    compatibility_test_status?: string;
    security_test_status?: string;
    regression_test_status?: string;
    nutritional_validation_status?: string;
    family_constraint_validation_status?: string;
    user_preference_validation_status?: string;
    ruleId?: string;
    ruleName?: string;
    confirmationRate?: number;
    confirmationDeadline?: string;
    currentDateTime?: string;
  }): {
    deployment_approved: boolean;
    deployment_action: string;
    deployment_status: string;
    all_tests_passed: boolean;
    passed_test_count: number;
    failed_test_count: number;
    failed_tests?: string[];
    deployment_ready_timestamp: string | null;
    deploymentApproved?: boolean;
    approvalStatus?: 'approved' | 'pending' | 'rejected';
    approvalReason?: string;
    recommendedDeploymentDate?: string | null;
  } {
    const requiredTestFields = [
      'functional_test_status',
      'performance_test_status',
      'compatibility_test_status',
      'security_test_status',
      'regression_test_status',
      'nutritional_validation_status',
      'family_constraint_validation_status',
      'user_preference_validation_status',
    ];
  
    const isTestEnvironmentInput = requiredTestFields.some(
      (field) => field in input
    );
  
    if (isTestEnvironmentInput) {
      for (const field of requiredTestFields) {
        if (!(field in input)) {
          throw new Error(`必須項目 ${field} が欠落しています`);
        }
      }
  
      const validStatuses = ['PASS', 'FAIL'];
      for (const field of requiredTestFields) {
        const value = (input as Record<string, string>)[field];
        if (!validStatuses.includes(value)) {
          throw new Error(
            `検証ステータス ${value} は無効です。PASS または FAIL を指定してください`
          );
        }
      }
  
      const failedTests: string[] = [];
      let passedCount = 0;
  
      for (const field of requiredTestFields) {
        const value = (input as Record<string, string>)[field];
        if (value === 'FAIL') {
          failedTests.push(field);
        } else {
          passedCount++;
        }
      }
  
      const allTestsPassed = failedTests.length === 0;
      const failedCount = failedTests.length;
  
      const result: any = {
        deployment_approved: allTestsPassed,
        deployment_action: allTestsPassed
          ? '本番デプロイ実行可能'
          : 'デプロイ実行不可',
        deployment_status: allTestsPassed ? '承認済み' : '却下',
        all_tests_passed: allTestsPassed,
        passed_test_count: passedCount,
        failed_test_count: failedCount,
        deployment_ready_timestamp: allTestsPassed
          ? new Date().toISOString()
          : null,
      };
  
      if (!allTestsPassed) {
        result.failed_tests = failedTests;
      }
  
      return result;
    }
  
    const confirmationRate = input.confirmationRate ?? 0;
    const confirmationDeadline = input.confirmationDeadline ?? '';
  
    let approvalStatus: 'approved' | 'pending' | 'rejected';
    let deploymentApproved: boolean;
    let approvalReason: string;
    let recommendedDeploymentDate: string | null = null;
  
    if (confirmationRate >= 0.8) {
      approvalStatus = 'approved';
      deploymentApproved = true;
      approvalReason = `確認率${Math.round(confirmationRate * 100)}%で承認基準を満たしています`;
  
      if (confirmationDeadline) {
        const deadline = new Date(confirmationDeadline);
        const nextDay = new Date(deadline.getTime() + 24 * 60 * 60 * 1000);
        recommendedDeploymentDate = nextDay.toISOString();
      }
    } else if (confirmationRate >= 0.5) {
      approvalStatus = 'pending';
      deploymentApproved = false;
      approvalReason = `確認率${Math.round(confirmationRate * 100)}%で承認基準を下回っています`;
    } else {
      approvalStatus = 'rejected';
      deploymentApproved = false;
      approvalReason = `確認率${Math.round(confirmationRate * 100)}%で承認基準を下回っています`;
    }
  
    return {
      deploymentApproved,
      approvalStatus,
      approvalReason,
      recommendedDeploymentDate,
      deployment_approved: deploymentApproved,
      deployment_action: deploymentApproved
        ? '本番デプロイ実行可能'
        : 'デプロイ実行不可',
      deployment_status: approvalStatus === 'approved' ? '承認済み' : '却下',
      all_tests_passed: deploymentApproved,
      passed_test_count: deploymentApproved ? 8 : 0,
      failed_test_count: deploymentApproved ? 0 : 1,
      deployment_ready_timestamp: deploymentApproved
        ? new Date().toISOString()
        : null,
    };
  }
  return { determineDeploymentApproval };
})();
export const determineDeploymentApproval = __aivicBundle_113_determineDeploymentApproval.determineDeploymentApproval;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineDeploymentApproval */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateDeploymentGate exports=validateDeploymentGate */
const __aivicBundle_114_validateDeploymentGate = (() => {
  function validateDeploymentGate(
    validationResults: Array<{
      validationItemId: string;
      itemName: string;
      status: string;
      timestamp: string;
      details: string;
    }>
  ): {
    shouldRollback: boolean;
    failureCount: number;
    passedCount: number;
    totalValidationItems: number;
    failureDetails: Array<{
      validationItemId: string;
      itemName: string;
      failureReason: string;
      timestamp: string;
    }>;
    message: string;
    generatedAt: string;
  } {
    if (!validationResults || validationResults.length === 0) {
      throw new Error('検証結果が空です');
    }
  
    for (const item of validationResults) {
      if (
        !item.validationItemId ||
        !item.itemName ||
        !item.status ||
        !item.timestamp ||
        item.details === undefined
      ) {
        throw new Error('必須フィールドが不足しています');
      }
    }
  
    const failureDetails: Array<{
      validationItemId: string;
      itemName: string;
      failureReason: string;
      timestamp: string;
    }> = [];
  
    let passedCount = 0;
  
    for (const item of validationResults) {
      if (item.status === 'PASSED') {
        passedCount++;
      } else if (item.status === 'FAILED') {
        failureDetails.push({
          validationItemId: item.validationItemId,
          itemName: item.itemName,
          failureReason: item.details,
          timestamp: item.timestamp
        });
      }
    }
  
    const failureCount = failureDetails.length;
    const totalValidationItems = validationResults.length;
    const shouldRollback = failureCount > 0;
  
    let message: string;
    if (shouldRollback) {
      message = `ロールバック判定: ${failureCount}件の検証失敗が検出されました`;
    } else {
      message = `成功: すべての検証項目が合格しました`;
    }
  
    const generatedAt = new Date().toISOString();
  
    return {
      shouldRollback,
      failureCount,
      passedCount,
      totalValidationItems,
      failureDetails,
      message,
      generatedAt
    };
  }
  return { validateDeploymentGate };
})();
export const validateDeploymentGate: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_114_validateDeploymentGate.validateDeploymentGate as (...args: any[]) => any)(...args);
