/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateDeploymentGate exports=evaluateDeploymentGate */
const __aivicBundle_116_evaluateDeploymentGate = (() => {
  function evaluateDeploymentGate(input: any): any {
    const verificationResult = input;
    
    // Extract values with defaults
    const statusCode = verificationResult?.statusCode || 'UNKNOWN';
    const passRate = verificationResult?.passRate ?? 0;
    const validationMessage = verificationResult?.validationMessage || '';
    const timestamp = verificationResult?.timestamp || new Date();
    
    // Determine gate status based on verification state
    let gateStatus: 'pass' | 'fail' | 'conditional' = 'conditional';
    let canProceedToProduction = false;
    let hasError = false;
    let reason = '';
    let message = '';
    
    // If statusCode is UNKNOWN, it's an ambiguous/unclear state
    if (statusCode === 'UNKNOWN') {
      gateStatus = 'conditional';
      canProceedToProduction = false;
      hasError = false;
      reason = 'Verification result is ambiguous and unclear - UNKNOWN status detected';
      message = '条件付き実行: 検証結果が不明な状態です。本番デプロイは保留されます。';
    } else if (statusCode === 'PASS' || statusCode === 'APPROVED') {
      gateStatus = 'pass';
      canProceedToProduction = true;
      hasError = false;
      reason = 'All deployment gate criteria satisfied';
      message = 'Deployment approved and can proceed to production';
    } else if (statusCode === 'FAIL' || statusCode === 'REJECTED') {
      gateStatus = 'fail';
      canProceedToProduction = false;
      hasError = true;
      reason = 'Deployment gate failed - critical issues detected';
      message = 'Deployment blocked due to gate failures';
    }
    
    // Build result object matching test expectations
    const result = {
      status: gateStatus === 'conditional' ? 'CONDITIONAL_EXECUTION' : gateStatus.toUpperCase(),
      message: message,
      verificationStatus: statusCode,
      hasError: hasError,
      canProceedToProduction: canProceedToProduction,
      reason: reason,
      passRate: passRate,
      validationMessage: validationMessage,
      timestamp: timestamp.toISOString(),
      deploymentId: `deploy_${Date.now()}`,
      gateStatus: gateStatus,
      evaluationTimestamp: timestamp.toISOString(),
      criteriaEvaluationResults: [],
      overallRiskScore: 0,
      blockerCount: 0,
      warningCount: 0,
      approvalRecommendation: canProceedToProduction,
      approvalRecommendationReason: reason,
      nextReviewDate: new Date(timestamp.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString(),
      deploymentCanProceed: canProceedToProduction,
    };
    
    return result;
  }
  return { evaluateDeploymentGate };
})();
export const evaluateDeploymentGate = __aivicBundle_116_evaluateDeploymentGate.evaluateDeploymentGate;
/* AIVIC_FUNCTION_BUNDLE_END owner=evaluateDeploymentGate */

/* AIVIC_FUNCTION_BUNDLE_START owner=rankMenuCandidatesByConstraints exports=rankMenuCandidatesByConstraints */
const __aivicBundle_117_rankMenuCandidatesByConstraints = (() => {
  function rankMenuCandidatesByConstraints(
    menuCandidates: Array<{
      menu_id: string;
      satisfaction_score: number;
      budget: number;
      protein: number;
      cooking_time: number;
      registration_order: number;
    }>,
    constraints: {
      maxBudget: number;
      minProtein: number;
      maxCookingTime: number;
    }
  ): Array<{
    menu_id: string;
    satisfaction_score: number;
    budget: number;
    protein: number;
    cooking_time: number;
    registration_order: number;
  }> {
    const filtered = menuCandidates.filter(
      (menu) =>
        menu.budget <= constraints.maxBudget &&
        menu.protein >= constraints.minProtein &&
        menu.cooking_time <= constraints.maxCookingTime
    );
  
    const sorted = filtered.sort((a, b) => {
      if (b.satisfaction_score !== a.satisfaction_score) {
        return b.satisfaction_score - a.satisfaction_score;
      }
      return a.registration_order - b.registration_order;
    });
  
    return sorted;
  }
  return { rankMenuCandidatesByConstraints };
})();
